pub(crate) fn tg_is(ar: &mut crate::port::Cells, h: i32, id: i32) -> i32 {
    // 1 when h is a name object whose bytes are row `id` of the `sn` table.
    if h == 0 {
        return 0;
    }
    if pl_kind_of(ar, h) != 4 {
        return 0;
    }
    let n: i32 = SN_SPAN[(id * 2 + 1) as usize];
    let o: i32 = SN_SPAN[(id * 2 + 0) as usize];
    let mut i: i32 = 0;
    if pl_name_len(ar, h) != n {
        return 0;
    }
    while i < n {
        if pl_name_byte(ar, h, i) != SN_CHARS[(o + i) as usize] {
            return 0;
        }
        i += 1;
    }
    return 1;
}
pub(crate) fn tg_get(ar: &mut crate::port::Cells, dict: i32, id: i32) -> i32 {
    // The RAW value under the key whose bytes are row `id` of the `sn` table, 0 when absent;
    // a key that occurs twice answers its last. A stream answers from its dictionary.
    if dict == 0 {
        return 0;
    }
    let mut d: i32 = dict;
    let mut k: i32 = 0;
    let mut v: i32 = 0;
    let mut found: i32 = 0;
    if pl_kind_of(ar, d) == 8 {
        d = pl_stream_dict(ar, d);
    }
    if pl_kind_of(ar, d) != 7 {
        return 0;
    }
    k = pl_first(ar, d);
    while k != 0 {
        v = pl_next(ar, k);
        if tg_is(ar, k, id) == 1 {
            found = v;
        }
        if v == 0 {
            k = 0;
        } else {
            k = pl_next(ar, v);
        }
    }
    return found;
}
pub(crate) fn tg_dget(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, dict: i32, id: i32) -> i32 {
    // The RESOLVED value under a key of the `sn` table, 0 when absent.
    let v: i32 = tg_get(ar, dict, id);
    if v == 0 {
        return 0;
    }
    return pd_resolve(src, ar, dc, a, b, st, v);
}
pub(crate) fn tg_name_row(ar: &mut crate::port::Cells, h: i32, first: i32, count: i32) -> i32 {
    // Which of the `sn` rows first .. first+count-1 the name h is, else -1.
    let mut i: i32 = 0;
    if h == 0 {
        return -1;
    }
    while i < count {
        if tg_is(ar, h, first + i) == 1 {
            return i;
        }
        i += 1;
    }
    return -1;
}
pub(crate) fn tg_role_code(ar: &mut crate::port::Cells, h: i32) -> i32 {
    // The standard structure type a name object spells: its code (`sr`) plus 256 times the level
    // for H1, H2, ...; 0 when it is none of them (a custom type). `Hn` is matched by its numerals.
    if h == 0 {
        return 0;
    }
    if pl_kind_of(ar, h) != 4 {
        return 0;
    }
    let n: i32 = pl_name_len(ar, h);
    let mut i: i32 = 1;
    let mut lv: i32 = 0;
    let mut ok: i32 = 1;
    let mut c: i32 = 0;
    let mut r: i32 = 0;
    let mut o: i32 = 0;
    let mut m: i32 = 0;
    let mut j: i32 = 0;
    let mut same: i32 = 0;
    if (n >= 2) && (n <= 5) {
        if pl_name_byte(ar, h, 0) == 72 {
            while i < n {
                c = pl_name_byte(ar, h, i);
                if (c < 48) || (c > 57) {
                    ok = 0;
                }
                if ok == 1 {
                    lv = (lv * 10) + (c - 48);
                }
                i += 1;
            }
            if (ok == 1) && (lv >= 1) && (pl_name_byte(ar, h, 1) != 48) {
                return 17 + (lv * 256);
            }
        }
    }
    r = 0;
    while r < 52 {
        if (r + 1) != 17 {
            o = SR_OFFS[(r * 2 + 0) as usize];
            m = SR_OFFS[(r * 2 + 1) as usize];
            if m == n {
                same = 1;
                j = 0;
                while j < m {
                    if pl_name_byte(ar, h, j) != SR_CHARS[(o + j) as usize] {
                        same = 0;
                    }
                    j += 1;
                }
                if same == 1 {
                    return r + 1;
                }
            }
        }
        r += 1;
    }
    return 0;
}
pub(crate) fn tg_resolve_role(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, ss: &mut crate::port::Cells, nameh: i32) -> i32 {
    // Resolve a /S name to a standard structure type, following the RoleMap: the answer is the
    // code, plus 256 times how (`sh`), plus 65536 times the level of an Hn. A name that IS a
    // standard type is used as it is (poppler and pdf.js do the same) and the RoleMap entry that
    // would remap it is noted (how 5, bit 16); a custom name is followed through the RoleMap
    // to the first standard type, at most 24 steps (how 3: a loop).
    let rm: i32 = crate::port::cells_at(ss, SS_ROLEMAP);
    let mut cur: i32 = nameh;
    let mut steps: i32 = 0;
    let mut ent: i32 = 0;
    let mut rc: i32 = 0;
    let mut how: i32 = 0;
    let mut v: i32 = 0;
    let mut next: i32 = 0;
    while steps < 25 {
        rc = tg_role_code(ar, cur);
        ent = pl_name_entry(ar, cur);
        if rc != 0 {
            how = 0;
            if steps > 0 {
                how = 1;
            }
            if (steps == 0) && (rm != 0) {
                if pl_dict_find(ar, rm, ent) != 0 {
                    how = 5;
                }
            }
            return ((rc % 256) + (how * 256)) + ((rc / 256) * 65536);
        }
        if rm == 0 {
            return 512;
        }
        v = pl_dict_find(ar, rm, ent);
        if v == 0 {
            return 512;
        }
        next = pd_resolve(src, ar, dc, a, b, st, v);
        if next == 0 {
            return 512;
        }
        if pl_kind_of(ar, next) != 4 {
            return 512;
        }
        cur = next;
        steps += 1;
    }
    return 768;
}
pub(crate) fn tg_max(x: i32, y: i32) -> i32 {
    if x > y {
        return x;
    }
    return y;
}
pub(crate) fn tg_min(x: i32, y: i32) -> i32 {
    if x < y {
        return x;
    }
    return y;
}
pub(crate) fn tg_pm(x: i32, y: i32) -> i32 {
    // x per mille of y (y > 0), without overflow.
    if y <= 0 {
        return 0;
    }
    if x <= 2000000 {
        return (x * 1000) / y;
    }
    return x / ((y / 1000) + 1);
}
pub(crate) fn tg_text(ar: &mut crate::port::Cells, h: i32, mut txt: &mut crate::port::Cells, mut se: &mut crate::port::Cells, at: i32) -> i32 {
    // Decode a string (or name) into `txt` and put its run in se[at], se[at+1]. 1 if it was one.
    if h == 0 {
        return 0;
    }
    if (pl_kind_of(ar, h) != 5) && (pl_kind_of(ar, h) != 4) {
        return 0;
    }
    let s: i32 = crate::port::cells_len(txt);
    let n: i32 = px_text_push(ar, h, txt);
    crate::port::cells_set(se, at, s);
    crate::port::cells_set(se, at + 1, n);
    return 1;
}
pub(crate) fn tg_ht_init(mut h: &mut crate::port::Cells, n: i32) -> i32 {
    // An open-addressing table of (k1, k2, k3) -> value, room for n keys: 0 cap, 1 count, then 4
    // cells a slot (k1 k2 k3 value+1; 0 is empty).
    crate::port::cells_drop(h, 0);
    let hcap: i32 = (n * 2) + 17;
    let mut i: i32 = 0;
    crate::port::cells_push(h, hcap);
    crate::port::cells_push(h, 0);
    while i < (hcap * 4) {
        crate::port::cells_push(h, 0);
        i += 1;
    }
    return hcap;
}
pub(crate) fn tg_ht_slot(k1: i32, k2: i32, k3: i32, hcap: i32) -> i32 {
    let mut x: i32 = ((((k1 & 2147483647) % 1048573) * 1021) + (((k2 & 2147483647) % 1048573) * 77)) + (((k3 & 2147483647) % 1048573) * 3);
    x = x % hcap;
    return x;
}
pub(crate) fn tg_ht_put(mut h: &mut crate::port::Cells, k1: i32, k2: i32, k3: i32, v: i32) -> i32 {
    // Store v under the key; 1 when the key was already there (and nothing is stored), else 0.
    let hcap: i32 = crate::port::cells_at(h, 0);
    let mut s: i32 = tg_ht_slot(k1, k2, k3, hcap);
    let mut at: i32 = 0;
    let mut guard: i32 = 0;
    while guard < hcap {
        at = 2 + (s * 4);
        if crate::port::cells_at(h, at + 3) == 0 {
            crate::port::cells_set(h, at, k1);
            crate::port::cells_set(h, at + 1, k2);
            crate::port::cells_set(h, at + 2, k3);
            crate::port::cells_set(h, at + 3, v + 1);
            crate::port::cells_set(h, 1, crate::port::cells_at(h, 1) + 1);
            return 0;
        }
        if (crate::port::cells_at(h, at) == k1) && (crate::port::cells_at(h, at + 1) == k2) && (crate::port::cells_at(h, at + 2) == k3) {
            return 1;
        }
        s = (s + 1) % hcap;
        guard += 1;
    }
    return 1;
}
pub(crate) fn tg_ht_get(h: &mut crate::port::Cells, k1: i32, k2: i32, k3: i32) -> i32 {
    // The value under the key, -1 when absent.
    let hcap: i32 = crate::port::cells_at(h, 0);
    let mut s: i32 = tg_ht_slot(k1, k2, k3, hcap);
    let mut at: i32 = 0;
    let mut guard: i32 = 0;
    while guard < hcap {
        at = 2 + (s * 4);
        if crate::port::cells_at(h, at + 3) == 0 {
            return -1;
        }
        if (crate::port::cells_at(h, at) == k1) && (crate::port::cells_at(h, at + 1) == k2) && (crate::port::cells_at(h, at + 2) == k3) {
            return crate::port::cells_at(h, at + 3) - 1;
        }
        s = (s + 1) % hcap;
        guard += 1;
    }
    return -1;
}
pub(crate) fn tg_se_new(mut se: &mut crate::port::Cells, obj: i32, parent: i32, depth: i32) -> i32 {
    // Append an element row with every field at its default. Answers its row.
    let row: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let at: i32 = row * SE_STRIDE;
    let mut i: i32 = 0;
    while i < SE_STRIDE {
        crate::port::cells_push(se, 0);
        i += 1;
    }
    crate::port::cells_set(se, at + SE_OBJ, obj);
    crate::port::cells_set(se, at + SE_PARENT, parent);
    crate::port::cells_set(se, at + SE_DEPTH, depth);
    crate::port::cells_set(se, at + SE_ROLES, -1);
    crate::port::cells_set(se, at + SE_PG, -1);
    crate::port::cells_set(se, at + SE_KFIRST, -1);
    crate::port::cells_set(se, at + SE_ALT, -1);
    crate::port::cells_set(se, at + SE_ACT, -1);
    crate::port::cells_set(se, at + SE_EXP, -1);
    crate::port::cells_set(se, at + SE_LANG, -1);
    crate::port::cells_set(se, at + SE_LANGSRC, -1);
    crate::port::cells_set(se, at + SE_ID, -1);
    crate::port::cells_set(se, at + SE_TITLE, -1);
    crate::port::cells_set(se, at + SE_ROWSPAN, -1);
    crate::port::cells_set(se, at + SE_COLSPAN, -1);
    crate::port::cells_set(se, at + SE_HEADS, -1);
    crate::port::cells_set(se, at + SE_SUMM, -1);
    crate::port::cells_set(se, at + SE_FSC, -1);
    crate::port::cells_set(se, at + SE_FPG, -1);
    crate::port::cells_set(se, at + SE_TREG, -1);
    return row;
}
pub(crate) fn tg_sc_new(mut sc: &mut crate::port::Cells, elem: i32, kind: i32, page: i32, mcid: i32, stm: i32, stmown: i32) -> i32 {
    let row: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let at: i32 = row * SC_STRIDE;
    let mut i: i32 = 0;
    let mut fl: i32 = 0;
    while i < SC_STRIDE {
        crate::port::cells_push(sc, 0);
        i += 1;
    }
    if kind == 2 {
        fl = 1;
    }
    if page < 0 {
        fl += 2;
    }
    if mcid < 0 {
        fl += 128;
    }
    crate::port::cells_set(sc, at + SC_ELEM, elem);
    crate::port::cells_set(sc, at + SC_KIND, kind);
    crate::port::cells_set(sc, at + SC_PAGE, page);
    crate::port::cells_set(sc, at + SC_MCID, mcid);
    crate::port::cells_set(sc, at + SC_STM, stm);
    crate::port::cells_set(sc, at + SC_MARK, -1);
    crate::port::cells_set(sc, at + SC_GFIRST, -1);
    crate::port::cells_set(sc, at + SC_STMOWN, stmown);
    crate::port::cells_set(sc, at + SC_FLAGS, fl);
    crate::port::cells_set(sc, at + SC_BX0, 0);
    crate::port::cells_set(sc, at + SC_FIRSTG, -1);
    crate::port::cells_set(sc, at + SC_LASTG, -1);
    return row;
}
pub(crate) fn tg_owner(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, d: i32) -> i32 {
    // An attribute object's owner: 0 none, 1 Layout, 2 List, 3 PrintField, 4 Table, 5 Hyperlink, 6 other.
    let o: i32 = tg_dget(src, ar, dc, a, b, st, d, sn_o());
    if o == 0 {
        return 0;
    }
    if pl_kind_of(ar, o) != 4 {
        return 6;
    }
    if tg_is(ar, o, sn_layout()) == 1 {
        return 1;
    }
    if tg_is(ar, o, sn_list()) == 1 {
        return 2;
    }
    if tg_is(ar, o, sn_print_field()) == 1 {
        return 3;
    }
    if tg_is(ar, o, sn_table()) == 1 {
        return 4;
    }
    if tg_is(ar, o, sn_hyperlink()) == 1 {
        return 5;
    }
    return 6;
}
pub(crate) fn tg_ad_add(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, v: i32) -> i32 {
    // Add the attribute object v (a dictionary, or an array of them) to the list `ad` (handle,
    // owner), at most 12.
    if v == 0 {
        return 0;
    }
    if pl_kind_of(ar, v) == 7 {
        if crate::port::cells_len(ad) < 24 {
            let ow: i32 = tg_owner(src, ar, dc, a, b, st, v);
            crate::port::cells_push(ad, v);
            crate::port::cells_push(ad, ow);
        }
        return 0;
    }
    if pl_kind_of(ar, v) == 6 {
        let mut e: i32 = pl_first(ar, v);
        let mut eh: i32 = 0;
        let mut ow2: i32 = 0;
        while e != 0 {
            eh = pd_resolve(src, ar, dc, a, b, st, e);
            if (eh != 0) && (pl_kind_of(ar, eh) == 7) {
                if crate::port::cells_len(ad) < 24 {
                    ow2 = tg_owner(src, ar, dc, a, b, st, eh);
                    crate::port::cells_push(ad, eh);
                    crate::port::cells_push(ad, ow2);
                }
            }
            e = pl_next(ar, e);
        }
    }
    return 0;
}
pub(crate) fn tg_attrs(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, ss: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, eh: i32) -> i32 {
    // Gather an element's attribute objects, its own /A first and then the classes its /C names
    // through the ClassMap, into `ad` (handle, owner pairs).
    crate::port::cells_drop(ad, 0);
    let av: i32 = tg_dget(src, ar, dc, a, b, st, eh, sn_a());
    let cv: i32 = tg_dget(src, ar, dc, a, b, st, eh, sn_c());
    let cm: i32 = crate::port::cells_at(ss, SS_CLASSMAP);
    let mut e: i32 = 0;
    let mut nh: i32 = 0;
    let mut ent: i32 = 0;
    let mut vv: i32 = 0;
    tg_ad_add(src, ar, dc, a, b, st, ad, av);
    if (cv != 0) && (cm != 0) {
        if pl_kind_of(ar, cv) == 4 {
            ent = pl_name_entry(ar, cv);
            vv = pl_dict_find(ar, cm, ent);
            vv = pd_resolve(src, ar, dc, a, b, st, vv);
            tg_ad_add(src, ar, dc, a, b, st, ad, vv);
        }
        if pl_kind_of(ar, cv) == 6 {
            e = pl_first(ar, cv);
            while e != 0 {
                nh = pd_resolve(src, ar, dc, a, b, st, e);
                if (nh != 0) && (pl_kind_of(ar, nh) == 4) {
                    ent = pl_name_entry(ar, nh);
                    vv = pl_dict_find(ar, cm, ent);
                    vv = pd_resolve(src, ar, dc, a, b, st, vv);
                    tg_ad_add(src, ar, dc, a, b, st, ad, vv);
                }
                e = pl_next(ar, e);
            }
        }
    }
    return 0;
}
pub(crate) fn tg_attr(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, ad: &mut crate::port::Cells, owner: i32, key: i32) -> i32 {
    // The resolved value of attribute `key` in the first attribute object whose owner is `owner`
    // (or names none) that has it, 0 when no object does.
    let mut i: i32 = 0;
    let mut v: i32 = 0;
    let mut ow: i32 = 0;
    while i < crate::port::cells_len(ad) {
        ow = crate::port::cells_at(ad, i + 1);
        if (ow == owner) || (ow == 0) {
            v = tg_dget(src, ar, dc, a, b, st, crate::port::cells_at(ad, i), key);
            if v != 0 {
                return v;
            }
        }
        i += 2;
    }
    return 0;
}
pub(crate) fn tg_read_attrs(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut txt: &mut crate::port::Cells, ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, row: i32, eh: i32, role: i32) -> i32 {
    // The attributes P3.7 reads, by role: Scope Headers RowSpan ColSpan (TH, TD), Summary (Table),
    // ListNumbering (L). Looked up in the element's own /A, then its classes.
    let at: i32 = row * SE_STRIDE;
    let mut v: i32 = 0;
    let mut e: i32 = 0;
    let mut eh2: i32 = 0;
    let mut s: i32 = 0;
    let mut n: i32 = 0;
    let mut any: i32 = 0;
    if (role == RO_TH) || (role == RO_TD) || (role == RO_TABLE) || (role == RO_L) {
        tg_attrs(src, ar, dc, a, b, st, ss, ad, eh);
        if crate::port::cells_len(ad) > 0 {
            if (role == RO_TH) || (role == RO_TD) {
                v = tg_attr(src, ar, dc, a, b, st, ad, 4, sn_scope());
                if v != 0 {
                    if tg_is(ar, v, sn_row()) == 1 {
                        crate::port::cells_set(se, at + SE_SCOPE, 1);
                    }
                    if tg_is(ar, v, sn_column()) == 1 {
                        crate::port::cells_set(se, at + SE_SCOPE, 2);
                    }
                    if tg_is(ar, v, sn_both()) == 1 {
                        crate::port::cells_set(se, at + SE_SCOPE, 3);
                    }
                }
                v = tg_attr(src, ar, dc, a, b, st, ad, 4, sn_row_span());
                if (v != 0) && (pl_kind_of(ar, v) == 2) {
                    crate::port::cells_set(se, at + SE_ROWSPAN, pl_int_value(ar, v));
                }
                v = tg_attr(src, ar, dc, a, b, st, ad, 4, sn_col_span());
                if (v != 0) && (pl_kind_of(ar, v) == 2) {
                    crate::port::cells_set(se, at + SE_COLSPAN, pl_int_value(ar, v));
                }
                v = tg_attr(src, ar, dc, a, b, st, ad, 4, sn_headers());
                if (v != 0) && (pl_kind_of(ar, v) == 6) {
                    s = crate::port::cells_len(txt);
                    e = pl_first(ar, v);
                    while e != 0 {
                        eh2 = pd_resolve(src, ar, dc, a, b, st, e);
                        if (eh2 != 0) && (pl_kind_of(ar, eh2) == 5) {
                            if any > 0 {
                                crate::port::cells_push(txt, 32);
                                n += 1;
                            }
                            n += px_text_push(ar, eh2, txt);
                            any += 1;
                        }
                        e = pl_next(ar, e);
                    }
                    if any > 0 {
                        crate::port::cells_set(se, at + SE_HEADS, s);
                        crate::port::cells_set(se, at + (SE_HEADS + 1), n);
                    }
                }
            }
            if role == RO_TABLE {
                v = tg_attr(src, ar, dc, a, b, st, ad, 4, sn_summary());
                tg_text(ar, v, txt, se, at + SE_SUMM);
            }
            if role == RO_L {
                v = tg_attr(src, ar, dc, a, b, st, ad, 2, sn_list_numbering());
                if v != 0 {
                    crate::port::cells_set(se, at + SE_LISTNUM, 12);
                    if tg_is(ar, v, sn_none()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 1);
                    }
                    if tg_is(ar, v, sn_unordered()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 2);
                    }
                    if tg_is(ar, v, sn_ordered()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 3);
                    }
                    if tg_is(ar, v, sn_disc()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 4);
                    }
                    if tg_is(ar, v, sn_circle()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 5);
                    }
                    if tg_is(ar, v, sn_square()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 6);
                    }
                    if tg_is(ar, v, sn_decimal()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 7);
                    }
                    if tg_is(ar, v, sn_upper_roman()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 8);
                    }
                    if tg_is(ar, v, sn_lower_roman()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 9);
                    }
                    if tg_is(ar, v, sn_upper_alpha()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 10);
                    }
                    if tg_is(ar, v, sn_lower_alpha()) == 1 {
                        crate::port::cells_set(se, at + SE_LISTNUM, 11);
                    }
                }
            }
        }
    }
    return 0;
}
pub(crate) fn tg_page_of(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, idx: &mut crate::port::Cells, d: i32) -> i32 {
    // The page index a /Pg of dictionary d names (a reference to a page), -1 when it has none.
    let raw: i32 = tg_get(ar, d, sn_pg());
    if raw == 0 {
        return -1;
    }
    if pl_kind_of(ar, raw) != 9 {
        return -1;
    }
    return px_page_of(idx, pl_int_value(ar, raw));
}
pub(crate) fn tg_obj_of(ar: &mut crate::port::Cells, raw: i32) -> i32 {
    // The object number a raw value refers to, 0 when it is not a reference.
    if raw == 0 {
        return 0;
    }
    if pl_kind_of(ar, raw) != 9 {
        return 0;
    }
    return pl_int_value(ar, raw);
}
pub(crate) fn tg_kid(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, idx: &mut crate::port::Cells, mut txt: &mut crate::port::Cells, mut seen: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut sk: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut so: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, parent: i32, skrow: i32, raw: i32, depth: i32) -> i32 {
    // One entry of a /K: an element (read, recursively), a marked-content reference, an object
    // reference, or something that is none of them (kept as skipped). -1 when the source missed.
    let eh: i32 = pd_resolve(src, ar, dc, a, b, st, raw);
    let sat: i32 = skrow * SK_STRIDE;
    let pat: i32 = parent * SE_STRIDE;
    let mut kind: i32 = 0;
    let mut ty: i32 = 0;
    let mut isel: i32 = 0;
    let mut ismcr: i32 = 0;
    let mut isobjr: i32 = 0;
    let mut obj: i32 = 0;
    let mut child: i32 = 0;
    let mut row: i32 = 0;
    let mut pgi: i32 = 0;
    let mut stmraw: i32 = 0;
    let mut stmo: i32 = 0;
    let mut stmown: i32 = 0;
    let mut mcidv: i32 = 0;
    let mut mv: i32 = 0;
    let mut ph: i32 = 0;
    let mut oh: i32 = 0;
    let mut okind: i32 = 0;
    let mut sub: i32 = 0;
    if ps_missed(src) {
        return -1;
    }
    crate::port::cells_set(sk, sat + 0, 4);
    crate::port::cells_set(sk, sat + 1, -1);
    crate::port::cells_set(sk, sat + 2, 1);
    if eh == 0 {
        return 0;
    }
    kind = pl_kind_of(ar, eh);
    if kind == 2 {
        pgi = crate::port::cells_at(se, pat + SE_PG);
        if (crate::port::cells_len(sc) / SC_STRIDE) < TG_MAXSC {
            row = tg_sc_new(sc, parent, 2, pgi, pl_int_value(ar, eh), 0, 0);
            crate::port::cells_set(sk, sat + 0, 2);
            crate::port::cells_set(sk, sat + 1, row);
            crate::port::cells_set(sk, sat + 2, 0);
            crate::port::cells_set(se, pat + SE_NCONT, crate::port::cells_at(se, pat + SE_NCONT) + 1);
        } else {
            crate::port::cells_set(sk, sat + 2, 5);
            crate::port::cells_set(ss, SS_LIMITS, crate::port::cells_at(ss, SS_LIMITS) | 4);
        }
        return 0;
    }
    if kind != 7 {
        return 0;
    }
    ty = tg_dget(src, ar, dc, a, b, st, eh, sn_type());
    if tg_is(ar, ty, sn_mcr()) == 1 {
        ismcr = 1;
    }
    if tg_is(ar, ty, sn_objr()) == 1 {
        isobjr = 1;
    }
    if tg_is(ar, ty, sn_struct_elem()) == 1 {
        isel = 1;
    }
    if (isel == 0) && (ismcr == 0) && (isobjr == 0) {
        if tg_get(ar, eh, sn_s()) != 0 {
            isel = 1;
        }
        if (isel == 0) && (tg_get(ar, eh, sn_mcid()) != 0) {
            ismcr = 1;
        }
        if (isel == 0) && (ismcr == 0) && (tg_get(ar, eh, sn_obj()) != 0) {
            isobjr = 1;
        }
    }
    if ismcr == 1 {
        if (crate::port::cells_len(sc) / SC_STRIDE) >= TG_MAXSC {
            crate::port::cells_set(sk, sat + 2, 5);
            crate::port::cells_set(ss, SS_LIMITS, crate::port::cells_at(ss, SS_LIMITS) | 4);
            return 0;
        }
        pgi = tg_page_of(src, ar, dc, a, b, st, idx, eh);
        if pgi < 0 {
            pgi = crate::port::cells_at(se, pat + SE_PG);
        }
        mv = tg_dget(src, ar, dc, a, b, st, eh, sn_mcid());
        stmraw = tg_get(ar, eh, sn_stm());
        stmo = tg_obj_of(ar, stmraw);
        stmraw = tg_get(ar, eh, sn_stm_own());
        stmown = tg_obj_of(ar, stmraw);
        mcidv = px_int_of(ar, mv, -1);
        row = tg_sc_new(sc, parent, 1, pgi, mcidv, stmo, stmown);
        crate::port::cells_set(sk, sat + 0, 2);
        crate::port::cells_set(sk, sat + 1, row);
        crate::port::cells_set(sk, sat + 2, 0);
        crate::port::cells_set(se, pat + SE_NCONT, crate::port::cells_at(se, pat + SE_NCONT) + 1);
        return 0;
    }
    if isobjr == 1 {
        pgi = tg_page_of(src, ar, dc, a, b, st, idx, eh);
        if pgi < 0 {
            pgi = crate::port::cells_at(se, pat + SE_PG);
        }
        ph = tg_get(ar, eh, sn_obj());
        oh = pd_resolve(src, ar, dc, a, b, st, ph);
        okind = 0;
        if (oh != 0) && ((pl_kind_of(ar, oh) == 7) || (pl_kind_of(ar, oh) == 8)) {
            sub = tg_dget(src, ar, dc, a, b, st, oh, sn_subtype());
            okind = 5;
            if tg_is(ar, sub, sn_link()) == 1 {
                okind = 1;
            }
            if tg_is(ar, sub, sn_widget()) == 1 {
                okind = 2;
            }
            if tg_is(ar, sub, sn_form()) == 1 {
                okind = 3;
            }
            if tg_is(ar, sub, sn_image()) == 1 {
                okind = 4;
            }
        }
        row = crate::port::cells_len(so) / SO_STRIDE;
        crate::port::cells_push(so, parent);
        crate::port::cells_push(so, pgi);
        crate::port::cells_push(so, tg_obj_of(ar, ph));
        crate::port::cells_push(so, okind);
        crate::port::cells_push(so, 0);
        crate::port::cells_push(so, 0);
        crate::port::cells_push(so, 0);
        crate::port::cells_push(so, 0);
        crate::port::cells_set(sk, sat + 0, 3);
        crate::port::cells_set(sk, sat + 1, row);
        crate::port::cells_set(sk, sat + 2, 0);
        crate::port::cells_set(se, pat + SE_NOBJR, crate::port::cells_at(se, pat + SE_NOBJR) + 1);
        return 0;
    }
    if isel == 1 {
        if ((crate::port::cells_len(se) / SE_STRIDE) + 1) >= TG_MAXELEMS {
            crate::port::cells_set(sk, sat + 2, 4);
            crate::port::cells_set(ss, SS_LIMITS, crate::port::cells_at(ss, SS_LIMITS) | 1);
            return 0;
        }
        if (depth + 1) >= TG_MAXDEPTH {
            crate::port::cells_set(sk, sat + 2, 3);
            crate::port::cells_set(ss, SS_LIMITS, crate::port::cells_at(ss, SS_LIMITS) | 2);
            crate::port::cells_set(se, pat + SE_BITS, crate::port::cells_at(se, pat + SE_BITS) | 32);
            return 0;
        }
        obj = tg_obj_of(ar, raw);
        if obj > 0 {
            if px_seen_mark(seen, obj) == 1 {
                crate::port::cells_set(sk, sat + 2, 2);
                crate::port::cells_set(ss, SS_LIMITS, crate::port::cells_at(ss, SS_LIMITS) | 8);
                return 0;
            }
        }
        child = tg_elem(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, eh, obj, parent, depth + 1);
        if child < 0 {
            return -1;
        }
        crate::port::cells_set(sk, sat + 0, 1);
        crate::port::cells_set(sk, sat + 1, child);
        crate::port::cells_set(sk, sat + 2, 0);
        crate::port::cells_set(se, pat + SE_NELEM, crate::port::cells_at(se, pat + SE_NELEM) + 1);
        return 0;
    }
    crate::port::cells_set(sk, sat + 2, 6);
    return 0;
}
pub(crate) fn tg_kids(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, idx: &mut crate::port::Cells, mut txt: &mut crate::port::Cells, mut seen: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut sk: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut so: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, row: i32, kraw: i32, depth: i32) -> i32 {
    // Read element `row`'s /K (raw value kraw): reserve one `sk` row per entry, then read each.
    let kh: i32 = pd_resolve(src, ar, dc, a, b, st, kraw);
    let at: i32 = row * SE_STRIDE;
    let first: i32 = crate::port::cells_len(sk) / SK_STRIDE;
    let mut n: i32 = 1;
    let mut i: i32 = 0;
    let mut e: i32 = 0;
    let mut r: i32 = 0;
    if kh == 0 {
        return 0;
    }
    if pl_kind_of(ar, kh) == 6 {
        n = pl_count(ar, kh);
    }
    if n > 1000000 {
        n = 1000000;
    }
    while i < (n * SK_STRIDE) {
        crate::port::cells_push(sk, 0);
        i += 1;
    }
    crate::port::cells_set(se, at + SE_KFIRST, first);
    crate::port::cells_set(se, at + SE_KCOUNT, n);
    if pl_kind_of(ar, kh) == 6 {
        e = pl_first(ar, kh);
        i = 0;
        while (e != 0) && (i < n) {
            r = tg_kid(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, first + i, e, depth);
            if r < 0 {
                return -1;
            }
            i += 1;
            e = pl_next(ar, e);
        }
    } else {
        r = tg_kid(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, first, kraw, depth);
        if r < 0 {
            return -1;
        }
    }
    return 0;
}
pub(crate) fn tg_elem(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, idx: &mut crate::port::Cells, mut txt: &mut crate::port::Cells, mut seen: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut sk: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut so: &mut crate::port::Cells, mut ad: &mut crate::port::Cells, eh: i32, obj: i32, parent: i32, depth: i32) -> i32 {
    // Read the structure element dictionary eh (object number obj, 0 direct) as a child of row
    // `parent`, then its kids. Answers its row, or -1 when the source missed.
    let row: i32 = tg_se_new(se, obj, parent, depth);
    let at: i32 = row * SE_STRIDE;
    let pat: i32 = parent * SE_STRIDE;
    let mut sh: i32 = 0;
    let mut rr: i32 = 0;
    let mut code: i32 = 0;
    let mut how: i32 = 0;
    let mut lvl: i32 = 0;
    let mut v: i32 = 0;
    let mut pgi: i32 = 0;
    let mut bits: i32 = 0;
    let mut sd: i32 = 0;
    let mut hl: i32 = 0;
    let mut prole: i32 = 0;
    let mut kraw: i32 = 0;
    let mut rc: i32 = 0;
    if depth > crate::port::cells_at(ss, SS_MAXDEPTH) {
        crate::port::cells_set(ss, SS_MAXDEPTH, depth);
    }
    crate::port::cells_set(ss, SS_ELEMS, crate::port::cells_at(ss, SS_ELEMS) + 1);
    sh = tg_dget(src, ar, dc, a, b, st, eh, sn_s());
    if (sh != 0) && (pl_kind_of(ar, sh) == 4) {
        tg_text(ar, sh, txt, se, at + SE_ROLES);
        rr = tg_resolve_role(src, ar, dc, a, b, st, ss, sh);
        code = rr % 256;
        how = (rr / 256) % 256;
        lvl = rr / 65536;
    } else {
        how = 4;
    }
    crate::port::cells_set(se, at + SE_ROLE, code);
    crate::port::cells_set(se, at + SE_HOW, how);
    crate::port::cells_set(se, at + SE_LEVEL, lvl);
    if how == 1 {
        crate::port::cells_set(ss, SS_CUSTOM, crate::port::cells_at(ss, SS_CUSTOM) + 1);
    }
    if (how == 2) || (how == 3) {
        crate::port::cells_set(ss, SS_UNRESOLVED, crate::port::cells_at(ss, SS_UNRESOLVED) + 1);
    }
    if how == 5 {
        bits |= 16;
        crate::port::cells_set(ss, SS_SHADOWED, crate::port::cells_at(ss, SS_SHADOWED) + 1);
    }
    pgi = tg_page_of(src, ar, dc, a, b, st, idx, eh);
    if pgi >= 0 {
        crate::port::cells_set(se, at + SE_PG, pgi);
        crate::port::cells_set(se, at + SE_PGOWN, 1);
    } else {
        crate::port::cells_set(se, at + SE_PG, crate::port::cells_at(se, pat + SE_PG));
    }
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_alt());
    tg_text(ar, v, txt, se, at + SE_ALT);
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_actual_text());
    tg_text(ar, v, txt, se, at + SE_ACT);
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_e());
    tg_text(ar, v, txt, se, at + SE_EXP);
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_lang());
    tg_text(ar, v, txt, se, at + SE_LANG);
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_id());
    tg_text(ar, v, txt, se, at + SE_ID);
    v = tg_dget(src, ar, dc, a, b, st, eh, sn_t());
    tg_text(ar, v, txt, se, at + SE_TITLE);
    if crate::port::cells_at(se, at + SE_LANG) >= 0 {
        crate::port::cells_set(se, at + SE_LANGSRC, row);
    } else {
        crate::port::cells_set(se, at + SE_LANGSRC, crate::port::cells_at(se, pat + SE_LANGSRC));
    }
    prole = crate::port::cells_at(se, pat + SE_ROLE);
    sd = crate::port::cells_at(se, pat + SE_SDEPTH);
    if prole == RO_SECT {
        sd += 1;
    }
    crate::port::cells_set(se, at + SE_SDEPTH, sd);
    if (code == RO_H) || (code == RO_HN) || (code == RO_TITLE) {
        crate::port::cells_set(se, at + SE_INH, 1);
    } else {
        crate::port::cells_set(se, at + SE_INH, crate::port::cells_at(se, pat + SE_INH));
    }
    if code == RO_HN {
        crate::port::cells_set(se, at + SE_HLEV, tg_min(lvl, 99));
    }
    if code == RO_H {
        hl = tg_min(tg_max(sd, 1), 6);
        crate::port::cells_set(se, at + SE_HLEV, hl);
        bits |= 1;
    }
    if tg_get(ar, eh, sn_a()) != 0 {
        bits |= 2;
    }
    if tg_get(ar, eh, sn_c()) != 0 {
        bits |= 4;
    }
    if obj == 0 {
        bits |= 8;
    }
    kraw = tg_get(ar, eh, sn_k());
    if kraw != 0 {
        bits |= 64;
    }
    crate::port::cells_set(se, at + SE_BITS, crate::port::cells_at(se, at + SE_BITS) | bits);
    rc = tg_read_attrs(src, ar, dc, a, b, st, txt, ss, se, ad, row, eh, code);
    if ps_missed(src) {
        return -1;
    }
    if kraw != 0 {
        rc = tg_kids(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, ad, row, kraw, depth);
        if rc < 0 {
            return -1;
        }
    }
    crate::port::cells_set(se, at + SE_SIZE, (crate::port::cells_len(se) / SE_STRIDE) - row);
    return row;
}
pub(crate) fn tg_nums(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, node: i32, depth: i32, mut out: &mut crate::port::Cells) -> i32 {
    // Every (integer key, raw value) of a number tree, appended to `out` two cells a pair: the
    // ParentTree. At most 12 deep and `TG_MAXPT` nodes; a loop costs that and no more.
    if depth > 12 {
        return 0;
    }
    if node == 0 {
        return 0;
    }
    if pl_kind_of(ar, node) != 7 {
        return 0;
    }
    let left: i32 = crate::port::cells_at(ss, SS_BUDGET);
    if left <= 0 {
        return 0;
    }
    crate::port::cells_set(ss, SS_BUDGET, left - 1);
    let nums: i32 = tg_dget(src, ar, dc, a, b, st, node, sn_nums());
    let kids: i32 = tg_dget(src, ar, dc, a, b, st, node, sn_kids());
    let mut k: i32 = 0;
    let mut v: i32 = 0;
    let mut kr: i32 = 0;
    if (nums != 0) && (pl_kind_of(ar, nums) == 6) {
        k = pl_first(ar, nums);
        while k != 0 {
            v = pl_next(ar, k);
            if v == 0 {
                k = 0;
            } else {
                kr = pd_resolve(src, ar, dc, a, b, st, k);
                if (kr != 0) && (pl_kind_of(ar, kr) == 2) {
                    crate::port::cells_push(out, pl_int_value(ar, kr));
                    crate::port::cells_push(out, v);
                }
                k = pl_next(ar, v);
            }
        }
    }
    if (kids != 0) && (pl_kind_of(ar, kids) == 6) {
        k = pl_first(ar, kids);
        while k != 0 {
            kr = pd_resolve(src, ar, dc, a, b, st, k);
            tg_nums(src, ar, dc, a, b, st, ss, kr, depth + 1, out);
            k = pl_next(ar, k);
        }
    }
    return 0;
}
pub(crate) fn tg_key_of(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, d: i32, id: i32) -> i32 {
    // The integer under key `id` of dictionary d (/StructParents, /StructParent), -1 when absent.
    let v: i32 = tg_dget(src, ar, dc, a, b, st, d, id);
    if v == 0 {
        return -1;
    }
    return px_int_of(ar, v, -1);
}
pub(crate) fn tg_parent_tree(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, pg: &mut crate::port::Cells, mut w: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut so: &mut crate::port::Cells, mut wk: &mut crate::port::Cells, rooth: i32) -> i32 {
    // Verify the tree against its ParentTree: for every marked-content reference, the entry the
    // ParentTree holds for (the page's or the Form XObject's /StructParents, MCID) must be the
    // element that claims it; for every object reference, the object's /StructParent entry.
    crate::port::cells_drop(w, 0);
    let ptree: i32 = tg_dget(src, ar, dc, a, b, st, rooth, sn_parent_tree());
    let nsc: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let nso: i32 = crate::port::cells_len(so) / SO_STRIDE;
    let mut i: i32 = 0;
    let mut key: i32 = 0;
    let mut pi: i32 = 0;
    let mut at: i32 = 0;
    let mut stm: i32 = 0;
    let mut mcid: i32 = 0;
    let mut dict: i32 = 0;
    let mut vh: i32 = 0;
    let mut ent: i32 = 0;
    let mut want: i32 = 0;
    let mut flag: i32 = 0;
    let mut npairs: i32 = 0;
    let mut got: i32 = 0;
    crate::port::cells_set(ss, SS_BUDGET, TG_MAXPT);
    tg_nums(src, ar, dc, a, b, st, ss, ptree, 0, w);
    if ps_missed(src) {
        return -1;
    }
    npairs = crate::port::cells_len(w) / 2;
    crate::port::cells_set(ss, SS_PTKEYS, npairs);
    tg_ht_init(wk, npairs);
    i = 0;
    while i < npairs {
        tg_ht_put(wk, crate::port::cells_at(w, i * 2), 0, 0, i);
        i += 1;
    }
    i = 0;
    while i < nsc {
        at = i * SC_STRIDE;
        pi = crate::port::cells_at(sc, at + SC_PAGE);
        stm = crate::port::cells_at(sc, at + SC_STM);
        mcid = crate::port::cells_at(sc, at + SC_MCID);
        flag = 0;
        key = -1;
        if (mcid >= 0) && (pi >= 0) && (pi < pd_pg_count(pg)) {
            if stm == 0 {
                dict = pd_resolve(src, ar, dc, a, b, st, pd_pg_node(pg, pi));
            } else {
                dict = pd_get(src, ar, dc, a, b, st, stm);
            }
            if dict != 0 {
                key = tg_key_of(src, ar, dc, a, b, st, dict, sn_struct_parents());
            }
        }
        if key >= 0 {
            got = tg_ht_get(wk, key, 0, 0);
            if got >= 0 {
                vh = pd_resolve(src, ar, dc, a, b, st, crate::port::cells_at(w, (got * 2) + 1));
                if (vh != 0) && (pl_kind_of(ar, vh) == 6) {
                    ent = px_nth(ar, vh, mcid);
                    want = crate::port::cells_at(se, (crate::port::cells_at(sc, at + SC_ELEM) * SE_STRIDE) + SE_OBJ);
                    if (ent != 0) && (pl_kind_of(ar, ent) == 9) {
                        if (want == 0) || (pl_int_value(ar, ent) == want) {
                            flag = 16;
                        } else {
                            flag = 32;
                        }
                    } else {
                        flag = 64;
                    }
                } else {
                    flag = 64;
                }
            } else {
                flag = 64;
            }
        } else {
            flag = 64;
        }
        if (crate::port::cells_at(sc, at + SC_FLAGS) & 128) == 128 {
            flag = 0;
        }
        if flag == 16 {
            crate::port::cells_set(ss, SS_PTOK, crate::port::cells_at(ss, SS_PTOK) + 1);
        }
        if flag == 32 {
            crate::port::cells_set(ss, SS_PTBAD, crate::port::cells_at(ss, SS_PTBAD) + 1);
        }
        if flag == 64 {
            crate::port::cells_set(ss, SS_PTNONE, crate::port::cells_at(ss, SS_PTNONE) + 1);
        }
        crate::port::cells_set(sc, at + SC_FLAGS, crate::port::cells_at(sc, at + SC_FLAGS) | flag);
        i += 1;
    }
    i = 0;
    while i < nso {
        at = i * SO_STRIDE;
        want = crate::port::cells_at(se, (crate::port::cells_at(so, at) * SE_STRIDE) + SE_OBJ);
        dict = pd_get(src, ar, dc, a, b, st, crate::port::cells_at(so, at + 2));
        key = -1;
        if dict != 0 {
            key = tg_key_of(src, ar, dc, a, b, st, dict, sn_struct_parent());
        }
        flag = 3;
        if key >= 0 {
            got = tg_ht_get(wk, key, 0, 0);
            if got >= 0 {
                ent = crate::port::cells_at(w, (got * 2) + 1);
                if (ent != 0) && (pl_kind_of(ar, ent) == 9) {
                    if (want == 0) || (pl_int_value(ar, ent) == want) {
                        flag = 1;
                    } else {
                        flag = 2;
                    }
                }
            }
        }
        crate::port::cells_set(so, at + 4, flag);
        i += 1;
    }
    if ps_missed(src) {
        return -1;
    }
    return 0;
}
pub fn tg_read(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut pg: &mut crate::port::Cells, mut idx: &mut crate::port::Cells, mut txt: &mut crate::port::Cells, mut w: &mut crate::port::Cells, mut seen: &mut crate::port::Cells, mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, mut sk: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut so: &mut crate::port::Cells, mut wk: &mut crate::port::Cells, md: &mut crate::port::Cells) -> i32 {
    // The structure tree of an opened document (`pd-open` 0, `pd-pages`, `px-index-build`): the
    // catalog's /MarkInfo and /Lang, the StructTreeRoot, its RoleMap and ClassMap, every element, and
    // the ParentTree check. `ss se sk sc so` are cleared; `txt` is APPENDED to; `w` and `wk` are scratch;
    // `md` is `emon.pdfmeta`'s header (empty when it has not run: the PDF/UA part is then -1).
    // Answers the number of elements (0 when the document is not tagged), or -1 when the source missed
    // (re-run on a fresh view; nothing here is kept).
    crate::port::cells_drop(ss, 0);
    crate::port::cells_drop(se, 0);
    crate::port::cells_drop(sk, 0);
    crate::port::cells_drop(sc, 0);
    crate::port::cells_drop(so, 0);
    let mut i: i32 = 0;
    let root: i32 = pd_root(dc);
    let mut mi: i32 = 0;
    let mut v: i32 = 0;
    let mut sroot: i32 = 0;
    let mut rm: i32 = 0;
    let mut cm: i32 = 0;
    let mut rc: i32 = 0;
    let mut kraw: i32 = 0;
    let mut robj: i32 = 0;
    while i < SS_SIZE {
        crate::port::cells_push(ss, 0);
        i += 1;
    }
    crate::port::cells_set(ss, SS_MARKED, -1);
    crate::port::cells_set(ss, SS_SUSPECTS, -1);
    crate::port::cells_set(ss, SS_USERPROPS, -1);
    crate::port::cells_set(ss, SS_UAPART, -1);
    crate::port::cells_set(ss, SS_UAREV, -1);
    crate::port::cells_set(ss, SS_LANG, -1);
    crate::port::cells_set(ss, SS_COV, -1);
    crate::port::cells_set(ss, SS_DIV, -1);
    crate::port::cells_set(ss, SS_ORD, -1);
    crate::port::cells_set(ss, SS_HDR, -1);
    crate::port::cells_set(ss, SS_LV, -1);
    crate::port::cells_set(ss, SS_ART, -1);
    crate::port::cells_set(ss, SS_NESTR, -1);
    crate::port::cells_set(ss, SS_ROOTOBJ, 0);
    crate::port::cells_set(ss, SS_PAGES, pd_pg_count(pg));
    if root == 0 {
        return 0;
    }
    mi = tg_dget(src, ar, dc, a, b, st, root, sn_mark_info());
    if (mi != 0) && (pl_kind_of(ar, mi) == 7) {
        v = tg_dget(src, ar, dc, a, b, st, mi, sn_marked());
        if (v != 0) && (pl_kind_of(ar, v) == 1) {
            crate::port::cells_set(ss, SS_MARKED, pl_int_value(ar, v));
        }
        v = tg_dget(src, ar, dc, a, b, st, mi, sn_suspects());
        if (v != 0) && (pl_kind_of(ar, v) == 1) {
            crate::port::cells_set(ss, SS_SUSPECTS, pl_int_value(ar, v));
        }
        v = tg_dget(src, ar, dc, a, b, st, mi, sn_user_properties());
        if (v != 0) && (pl_kind_of(ar, v) == 1) {
            crate::port::cells_set(ss, SS_USERPROPS, pl_int_value(ar, v));
        }
    }
    if crate::port::cells_len(md) > 59 {
        crate::port::cells_set(ss, SS_UAPART, crate::port::cells_at(md, 42));
        crate::port::cells_set(ss, SS_UAREV, crate::port::cells_at(md, 59));
        crate::port::cells_set(ss, SS_LANG, crate::port::cells_at(md, 0));
        crate::port::cells_set(ss, SS_LANG + 1, crate::port::cells_at(md, 1));
    }
    sroot = tg_dget(src, ar, dc, a, b, st, root, sn_struct_tree_root());
    if ps_missed(src) {
        return -1;
    }
    if sroot == 0 {
        return 0;
    }
    if pl_kind_of(ar, sroot) != 7 {
        return 0;
    }
    crate::port::cells_set(ss, SS_PRESENT, 1);
    crate::port::cells_set(ss, SS_ROOT, sroot);
    px_seen_begin(seen, pd_object_count(dc));
    rm = tg_dget(src, ar, dc, a, b, st, sroot, sn_role_map());
    if (rm != 0) && (pl_kind_of(ar, rm) == 7) {
        crate::port::cells_set(ss, SS_ROLEMAP, rm);
        crate::port::cells_set(ss, SS_ROLEMAPN, pl_count(ar, rm) / 2);
    }
    cm = tg_dget(src, ar, dc, a, b, st, sroot, sn_class_map());
    if (cm != 0) && (pl_kind_of(ar, cm) == 7) {
        crate::port::cells_set(ss, SS_CLASSMAP, cm);
        crate::port::cells_set(ss, SS_CLASSMAPN, pl_count(ar, cm) / 2);
    }
    robj = tg_get(ar, root, sn_struct_tree_root());
    robj = tg_obj_of(ar, robj);
    tg_se_new(se, robj, -1, 0);
    crate::port::cells_set(ss, SS_ROOTOBJ, crate::port::cells_at(se, SE_OBJ));
    crate::port::cells_set(se, SE_HOW, 6);
    crate::port::cells_set(se, SE_BITS, 0);
    crate::port::cells_set(ss, SS_ELEMS, 1);
    crate::port::cells_set(ss, SS_CBUDGET, 0);
    kraw = tg_get(ar, sroot, sn_k());
    if kraw != 0 {
        crate::port::cells_set(se, SE_BITS, 64);
        rc = tg_kids(src, ar, dc, a, b, st, idx, txt, seen, ss, se, sk, sc, so, w, 0, kraw, 0);
        if rc < 0 {
            return -1;
        }
    }
    crate::port::cells_set(se, SE_SIZE, crate::port::cells_len(se) / SE_STRIDE);
    crate::port::cells_set(ss, SS_CONTENT, crate::port::cells_len(sc) / SC_STRIDE);
    crate::port::cells_set(ss, SS_OBJRS, crate::port::cells_len(so) / SO_STRIDE);
    if ps_missed(src) {
        return -1;
    }
    rc = tg_parent_tree(src, ar, dc, a, b, st, pg, w, ss, se, sc, so, wk, sroot);
    if rc < 0 {
        return -1;
    }
    return crate::port::cells_len(se) / SE_STRIDE;
}
pub(crate) fn tg_j_marks(mut ss: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mk: &mut crate::port::Cells, mut ha: &mut crate::port::Cells, mut hb: &mut crate::port::Cells) -> i32 {
    // Index the text layer's marked content by (page, Form XObject, MCID) and join every marked-
    // content reference to its `marks` row. A mark claimed twice keeps its first claimer (the other
    // reference is flagged `duplicate`); the rest is `no-mark`.
    let nmk: i32 = mk_count(mk);
    let nsc: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let mut m: i32 = 0;
    let mut mc: i32 = 0;
    let mut i: i32 = 0;
    let mut at: i32 = 0;
    let mut pi: i32 = 0;
    let mut got: i32 = 0;
    let mut fl: i32 = 0;
    let mut dup: i32 = 0;
    tg_ht_init(ha, nmk);
    crate::port::cells_drop(hb, 0);
    while m < nmk {
        crate::port::cells_push(hb, -1);
        mc = mk_get(mk, m, mkf_mcid());
        if mc >= 0 {
            dup = tg_ht_put(ha, mk_get(mk, m, mkf_page()), mk_get(mk, m, mkf_stm()), mc, m);
        }
        m += 1;
    }
    crate::port::cells_set(ss, SS_MARKS, nmk);
    while i < nsc {
        at = i * SC_STRIDE;
        pi = crate::port::cells_at(sc, at + SC_PAGE);
        fl = crate::port::cells_at(sc, at + SC_FLAGS);
        got = -1;
        if (pi >= 0) && (crate::port::cells_at(sc, at + SC_MCID) >= 0) {
            got = tg_ht_get(ha, pi + 1, crate::port::cells_at(sc, at + SC_STM), crate::port::cells_at(sc, at + SC_MCID));
        }
        if got >= 0 {
            crate::port::cells_set(sc, at + SC_MARK, got);
            crate::port::cells_set(sc, at + SC_GFIRST, mk_get(mk, got, mkf_gfirst()));
            crate::port::cells_set(sc, at + SC_GCOUNT, mk_get(mk, got, mkf_gcount()));
            if crate::port::cells_at(hb, got) >= 0 {
                fl |= 8;
                crate::port::cells_set(ss, SS_DUPS, crate::port::cells_at(ss, SS_DUPS) + 1);
            } else {
                crate::port::cells_set(hb, got, i);
            }
            crate::port::cells_set(ss, SS_JOINED, crate::port::cells_at(ss, SS_JOINED) + 1);
        } else {
            fl |= 4;
            crate::port::cells_set(ss, SS_UNJOINED, crate::port::cells_at(ss, SS_UNJOINED) + 1);
        }
        crate::port::cells_set(sc, at + SC_FLAGS, fl);
        i += 1;
    }
    return dup;
}
pub(crate) fn tg_j_glyphs(mut ss: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, gl: &mut crate::port::Cells, mk: &mut crate::port::Cells, fnt: &mut crate::port::Cells, hb: &mut crate::port::Cells, mut hh: &mut crate::port::Cells) -> i32 {
    // Give every glyph its owner: the structure element of its innermost marked content that carries an
    // MCID (through the reference that claimed it), or `artifact` (innermost /Artifact), or neither. The
    // owning reference collects the glyph's size, boldness and box; the type-size histogram `hh` (0.5 pt
    // buckets) collects every tagged glyph, for the body size.
    let ng: i32 = gl_count(gl);
    let mut g: i32 = 0;
    let mut m: i32 = 0;
    let mut decided: i32 = 0;
    let mut own: i32 = -1;
    let mut at: i32 = 0;
    let mut sz: i32 = 0;
    let mut bold: i32 = 0;
    let mut font: i32 = 0;
    let mut bk: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut n: i32 = 0;
    crate::port::cells_drop(hh, 0);
    while n < 4200 {
        crate::port::cells_push(hh, 0);
        n += 1;
    }
    crate::port::cells_set(ss, SS_GLYPHS, ng);
    while g < ng {
        m = gl_get(gl, g, gf_mark());
        decided = 0;
        own = -1;
        while (m >= 0) && (decided == 0) {
            if mk_get(mk, m, mkf_kind()) == 1 {
                decided = 2;
            } else if mk_get(mk, m, mkf_mcid()) >= 0 {
                decided = 1;
                own = crate::port::cells_at(hb, m);
            }
            if decided == 0 {
                m = mk_get(mk, m, mkf_parent());
            }
        }
        if decided == 2 {
            crate::port::cells_set(ss, SS_ARTG, crate::port::cells_at(ss, SS_ARTG) + 1);
        }
        if decided == 0 {
            crate::port::cells_set(ss, SS_UNTAGGED, crate::port::cells_at(ss, SS_UNTAGGED) + 1);
        }
        if (decided == 1) && (own < 0) {
            crate::port::cells_set(ss, SS_UNCLAIMED, crate::port::cells_at(ss, SS_UNCLAIMED) + 1);
        }
        if (decided == 1) && (own >= 0) {
            crate::port::cells_set(ss, SS_COVERED, crate::port::cells_at(ss, SS_COVERED) + 1);
            at = own * SC_STRIDE;
            sz = gl_get(gl, g, gf_size());
            bk = tg_min(sz / 50, 4095);
            if bk < 0 {
                bk = 0;
            }
            crate::port::cells_set(hh, bk, crate::port::cells_at(hh, bk) + 1);
            sz = (tg_min(tg_max(sz, 0), 6000) + 5) / 10;
            font = gl_get(gl, g, gf_font());
            bold = 0;
            if font >= 0 {
                if (fo_get(fnt, font, fnf_style()) & 1) == 1 {
                    bold = 1;
                }
            }
            x0 = gl_get(gl, g, ch_x0());
            y0 = gl_get(gl, g, ch_y0());
            x1 = gl_get(gl, g, ch_x1());
            y1 = gl_get(gl, g, ch_y1());
            if crate::port::cells_at(sc, at + SC_OWNG) == 0 {
                crate::port::cells_set(sc, at + SC_BX0, x0);
                crate::port::cells_set(sc, at + (SC_BX0 + 1), y0);
                crate::port::cells_set(sc, at + (SC_BX0 + 2), x1);
                crate::port::cells_set(sc, at + (SC_BX0 + 3), y1);
                crate::port::cells_set(sc, at + SC_FIRSTG, g);
            } else {
                crate::port::cells_set(sc, at + SC_BX0, tg_min(crate::port::cells_at(sc, at + SC_BX0), x0));
                crate::port::cells_set(sc, at + (SC_BX0 + 1), tg_min(crate::port::cells_at(sc, at + (SC_BX0 + 1)), y0));
                crate::port::cells_set(sc, at + (SC_BX0 + 2), tg_max(crate::port::cells_at(sc, at + (SC_BX0 + 2)), x1));
                crate::port::cells_set(sc, at + (SC_BX0 + 3), tg_max(crate::port::cells_at(sc, at + (SC_BX0 + 3)), y1));
            }
            crate::port::cells_set(sc, at + SC_LASTG, g);
            crate::port::cells_set(sc, at + SC_OWNG, crate::port::cells_at(sc, at + SC_OWNG) + 1);
            crate::port::cells_set(sc, at + SC_OWNSZ, crate::port::cells_at(sc, at + SC_OWNSZ) + sz);
            crate::port::cells_set(sc, at + SC_OWNBD, crate::port::cells_at(sc, at + SC_OWNBD) + bold);
        }
        g += 1;
    }
    return 0;
}
pub(crate) fn tg_j_sub(mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, sc: &mut crate::port::Cells, so: &mut crate::port::Cells) -> i32 {
    // Roll every marked-content reference's glyphs up its element's ancestors: the element's own
    // numbers, then the subtree's, the first reference (in tree order) that holds text and the box of
    // the subtree's text on that reference's page.
    let nsc: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let nso: i32 = crate::port::cells_len(so) / SO_STRIDE;
    let mut i: i32 = 0;
    let mut at: i32 = 0;
    let mut e: i32 = 0;
    let mut ea: i32 = 0;
    let mut g: i32 = 0;
    let mut pgx: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    while i < nsc {
        at = i * SC_STRIDE;
        e = crate::port::cells_at(sc, at + SC_ELEM);
        g = crate::port::cells_at(sc, at + SC_OWNG);
        pgx = crate::port::cells_at(sc, at + SC_PAGE);
        x0 = crate::port::cells_at(sc, at + SC_BX0);
        y0 = crate::port::cells_at(sc, at + (SC_BX0 + 1));
        x1 = crate::port::cells_at(sc, at + (SC_BX0 + 2));
        y1 = crate::port::cells_at(sc, at + (SC_BX0 + 3));
        ea = e * SE_STRIDE;
        crate::port::cells_set(se, ea + SE_OWNG, crate::port::cells_at(se, ea + SE_OWNG) + g);
        crate::port::cells_set(se, ea + SE_OWNSZ, crate::port::cells_at(se, ea + SE_OWNSZ) + crate::port::cells_at(sc, at + SC_OWNSZ));
        crate::port::cells_set(se, ea + SE_OWNBD, crate::port::cells_at(se, ea + SE_OWNBD) + crate::port::cells_at(sc, at + SC_OWNBD));
        while e >= 0 {
            ea = e * SE_STRIDE;
            crate::port::cells_set(se, ea + SE_SUBC, crate::port::cells_at(se, ea + SE_SUBC) + 1);
            if g > 0 {
                crate::port::cells_set(se, ea + SE_SUBG, crate::port::cells_at(se, ea + SE_SUBG) + g);
                crate::port::cells_set(se, ea + SE_SUBSZ, crate::port::cells_at(se, ea + SE_SUBSZ) + crate::port::cells_at(sc, at + SC_OWNSZ));
                crate::port::cells_set(se, ea + SE_SUBBD, crate::port::cells_at(se, ea + SE_SUBBD) + crate::port::cells_at(sc, at + SC_OWNBD));
                if crate::port::cells_at(se, ea + SE_FSC) < 0 {
                    crate::port::cells_set(se, ea + SE_FSC, i);
                    crate::port::cells_set(se, ea + SE_FPG, pgx);
                    crate::port::cells_set(se, ea + SE_BX0, x0);
                    crate::port::cells_set(se, ea + (SE_BX0 + 1), y0);
                    crate::port::cells_set(se, ea + (SE_BX0 + 2), x1);
                    crate::port::cells_set(se, ea + (SE_BX0 + 3), y1);
                } else if crate::port::cells_at(se, ea + SE_FPG) == pgx {
                    crate::port::cells_set(se, ea + SE_BX0, tg_min(crate::port::cells_at(se, ea + SE_BX0), x0));
                    crate::port::cells_set(se, ea + (SE_BX0 + 1), tg_min(crate::port::cells_at(se, ea + (SE_BX0 + 1)), y0));
                    crate::port::cells_set(se, ea + (SE_BX0 + 2), tg_max(crate::port::cells_at(se, ea + (SE_BX0 + 2)), x1));
                    crate::port::cells_set(se, ea + (SE_BX0 + 3), tg_max(crate::port::cells_at(se, ea + (SE_BX0 + 3)), y1));
                }
            }
            e = crate::port::cells_at(se, ea + SE_PARENT);
        }
        i += 1;
    }
    i = 0;
    while i < nso {
        e = crate::port::cells_at(so, i * SO_STRIDE);
        while e >= 0 {
            ea = e * SE_STRIDE;
            crate::port::cells_set(se, ea + SE_SUBC, crate::port::cells_at(se, ea + SE_SUBC) + 1);
            e = crate::port::cells_at(se, ea + SE_PARENT);
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn tg_j_order(mut ss: &mut crate::port::Cells, sc: &mut crate::port::Cells, gl: &mut crate::port::Cells) -> i32 {
    // Reading order against geometry: for each pair of consecutive marked-content references that hold
    // upright text on the same page, the tree is right when the second starts no more than half a line
    // above where the first ended (down the page, or along the line), or entirely to the right of it (the
    // next column). The glyph boxes are in page space, y down.
    let nsc: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let mut i: i32 = 0;
    let mut prev: i32 = -1;
    let mut ga: i32 = 0;
    let mut gb: i32 = 0;
    let mut ah: i32 = 0;
    let mut bh: i32 = 0;
    let mut h: i32 = 0;
    let mut up: i32 = 0;
    let mut agree: i32 = 0;
    while i < nsc {
        if crate::port::cells_at(sc, (i * SC_STRIDE) + SC_OWNG) > 0 {
            if prev >= 0 {
                if crate::port::cells_at(sc, (prev * SC_STRIDE) + SC_PAGE) == crate::port::cells_at(sc, (i * SC_STRIDE) + SC_PAGE) {
                    ga = crate::port::cells_at(sc, (prev * SC_STRIDE) + SC_LASTG);
                    gb = crate::port::cells_at(sc, (i * SC_STRIDE) + SC_FIRSTG);
                    if (gl_get(gl, ga, gf_rot()) == 0) && (gl_get(gl, gb, gf_rot()) == 0) {
                        ah = gl_get(gl, ga, ch_y1()) - gl_get(gl, ga, ch_y0());
                        bh = gl_get(gl, gb, ch_y1()) - gl_get(gl, gb, ch_y0());
                        h = tg_min(ah, bh);
                        if h <= 0 {
                            h = tg_max(ah, bh);
                        }
                        up = (gl_get(gl, ga, ch_y0()) + gl_get(gl, ga, ch_y1())) - (gl_get(gl, gb, ch_y0()) + gl_get(gl, gb, ch_y1()));
                        agree = 0;
                        if up <= h {
                            agree = 1;
                        }
                        if gl_get(gl, gb, ch_x0()) >= gl_get(gl, ga, ch_x1()) {
                            agree = 1;
                        }
                        crate::port::cells_set(ss, SS_TRANS, crate::port::cells_at(ss, SS_TRANS) + 1);
                        crate::port::cells_set(ss, SS_TRANSOK, crate::port::cells_at(ss, SS_TRANSOK) + agree);
                    }
                }
            }
            prev = i;
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn tg_class_bit(role: i32) -> i32 {
    // The class of informative structure a role belongs to, as a bit: 1 heading, 2 list, 4 table,
    // 8 figure, 16 section, 32 note-like (caption, quote, note, reference, code), 64 link, 128
    // table of contents. A paragraph, a span and the grouping types say nothing beyond blocks.
    if (role == RO_H) || (role == RO_HN) || (role == RO_TITLE) {
        return 1;
    }
    if (role >= RO_L) && (role <= RO_LBODY) {
        return 2;
    }
    if (role >= RO_TABLE) && (role <= RO_TFOOT) {
        return 4;
    }
    if (role == RO_FIGURE) || (role == RO_FORMULA) || (role == RO_FORM) {
        return 8;
    }
    if (role == RO_PART) || (role == RO_ART) || (role == RO_SECT) || (role == RO_ASIDE) {
        return 16;
    }
    if (role == RO_BLOCKQUOTE) || (role == RO_CAPTION) || (role == RO_QUOTE) || (role == RO_NOTE) {
        return 32;
    }
    if (role == RO_FENOTE) || (role == RO_REF) || (role == RO_BIB) || (role == RO_CODE) {
        return 32;
    }
    if (role == RO_LINK) || (role == RO_ANNOT) {
        return 64;
    }
    if (role >= RO_TOC) && (role <= RO_INDEX) {
        return 128;
    }
    return 0;
}
pub(crate) fn tg_nest_ok(role: i32, prole: i32) -> i32 {
    // Whether a role sits where the standard puts it: 1 yes, 0 no, -1 the standard says nothing.
    if role == RO_TR {
        if (prole == RO_TABLE) || (prole == RO_THEAD) || (prole == RO_TBODY) || (prole == RO_TFOOT) {
            return 1;
        }
        return 0;
    }
    if (role == RO_TH) || (role == RO_TD) {
        if prole == RO_TR {
            return 1;
        }
        return 0;
    }
    if (role == RO_THEAD) || (role == RO_TBODY) || (role == RO_TFOOT) {
        if prole == RO_TABLE {
            return 1;
        }
        return 0;
    }
    if role == RO_LI {
        if prole == RO_L {
            return 1;
        }
        return 0;
    }
    if (role == RO_LBL) || (role == RO_LBODY) {
        if prole == RO_LI {
            return 1;
        }
        return 0;
    }
    if role == RO_TOCI {
        if (prole == RO_TOC) || (prole == RO_TOCI) {
            return 1;
        }
        return 0;
    }
    return -1;
}
pub(crate) fn tg_j_classes(mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells) -> i32 {
    // Which classes of structure the tree uses (over elements that hold content), and how many of the
    // roles the standard places are where it places them.
    let nse: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let mut r: i32 = 1;
    let mut at: i32 = 0;
    let mut par: i32 = 0;
    let mut role: i32 = 0;
    let mut mask: i32 = 0;
    let mut v: i32 = 0;
    let mut bits: i32 = 0;
    let mut n: i32 = 0;
    while r < nse {
        at = r * SE_STRIDE;
        role = crate::port::cells_at(se, at + SE_ROLE);
        par = crate::port::cells_at(se, at + SE_PARENT);
        if crate::port::cells_at(se, at + SE_SUBC) > 0 {
            mask |= tg_class_bit(role);
        }
        v = tg_nest_ok(role, crate::port::cells_at(se, (par * SE_STRIDE) + SE_ROLE));
        if v >= 0 {
            crate::port::cells_set(ss, SS_NEST, crate::port::cells_at(ss, SS_NEST) + 1);
            crate::port::cells_set(ss, SS_NESTOK, crate::port::cells_at(ss, SS_NESTOK) + v);
        }
        if role == RO_TABLE {
            crate::port::cells_set(ss, SS_TABLES, crate::port::cells_at(ss, SS_TABLES) + 1);
        }
        if role == RO_L {
            crate::port::cells_set(ss, SS_LISTS, crate::port::cells_at(ss, SS_LISTS) + 1);
        }
        r += 1;
    }
    crate::port::cells_set(ss, SS_CLASSES, mask);
    bits = mask;
    while bits > 0 {
        n += bits % 2;
        bits = bits / 2;
    }
    crate::port::cells_set(ss, SS_NCLASSES, n);
    return 0;
}
pub(crate) fn tg_j_tables(sk: &mut crate::port::Cells, mut se: &mut crate::port::Cells) -> i32 {
    // Each table's shape from its rows: how many, how many columns (the sum of ColSpan over a row's
    // cells), and whether every row has as many (`regular`). Rows are found under the Table or its
    // THead, TBody and TFoot.
    let nse: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let mut r: i32 = 1;
    let mut at: i32 = 0;
    let mut p: i32 = 0;
    let mut pr: i32 = 0;
    let mut k: i32 = 0;
    let mut kn: i32 = 0;
    let mut c: i32 = 0;
    let mut cols: i32 = 0;
    let mut cs: i32 = 0;
    let mut tat: i32 = 0;
    while r < nse {
        at = r * SE_STRIDE;
        if crate::port::cells_at(se, at + SE_ROLE) == RO_TR {
            p = crate::port::cells_at(se, at + SE_PARENT);
            pr = crate::port::cells_at(se, (p * SE_STRIDE) + SE_ROLE);
            if (pr == RO_THEAD) || (pr == RO_TBODY) || (pr == RO_TFOOT) {
                p = crate::port::cells_at(se, (p * SE_STRIDE) + SE_PARENT);
                pr = crate::port::cells_at(se, (p * SE_STRIDE) + SE_ROLE);
            }
            if pr == RO_TABLE {
                cols = 0;
                k = crate::port::cells_at(se, at + SE_KFIRST);
                kn = crate::port::cells_at(se, at + SE_KCOUNT);
                c = 0;
                while (k >= 0) && (c < kn) {
                    if crate::port::cells_at(sk, (k + c) * SK_STRIDE) == 1 {
                        cs = crate::port::cells_at(sk, ((k + c) * SK_STRIDE) + 1) * SE_STRIDE;
                        if (crate::port::cells_at(se, cs + SE_ROLE) == RO_TH) || (crate::port::cells_at(se, cs + SE_ROLE) == RO_TD) {
                            cols += tg_max(crate::port::cells_at(se, cs + SE_COLSPAN), 1);
                        }
                    }
                    c += 1;
                }
                tat = p * SE_STRIDE;
                crate::port::cells_set(se, tat + SE_TROWS, crate::port::cells_at(se, tat + SE_TROWS) + 1);
                if crate::port::cells_at(se, tat + SE_TROWS) == 1 {
                    crate::port::cells_set(se, tat + SE_TCOLS, cols);
                    crate::port::cells_set(se, tat + SE_TREG, 1);
                } else if cols != crate::port::cells_at(se, tat + SE_TCOLS) {
                    crate::port::cells_set(se, tat + SE_TREG, 0);
                    crate::port::cells_set(se, tat + SE_TCOLS, tg_max(cols, crate::port::cells_at(se, tat + SE_TCOLS)));
                }
            }
        }
        r += 1;
    }
    return 0;
}
pub(crate) fn tg_label_kind(gl: &mut crate::port::Cells, g0: i32, g1: i32) -> i32 {
    // What a list label's first glyphs look like, as `lk` bits: a bullet, decimal digits, a letter (a
    // Roman numeral's letters count for both), several Roman letters; 0 when it is none. Leading
    // parentheses and spaces, a trailing period, the first space or `)` `:` `]` are not part of it.
    let mut g: i32 = g0;
    let mut cp: i32 = 0;
    let mut n: i32 = 0;
    let mut sym: i32 = 0;
    let mut dig: i32 = 0;
    let mut low: i32 = 0;
    let mut upr: i32 = 0;
    let mut rl: i32 = 0;
    let mut ru: i32 = 0;
    let mut stop: i32 = 0;
    let mut mask: i32 = 0;
    while (g <= g1) && (g < (g0 + 12)) && (stop == 0) {
        cp = gl_get(gl, g, ch_cp());
        if (cp == 32) || (cp == 160) || (cp == 41) || (cp == 58) || (cp == 93) || (cp == 40) || (cp == 91) {
            if n > 0 {
                stop = 1;
            }
        } else if cp != 46 {
            n += 1;
            if (cp >= 48) && (cp <= 57) {
                dig += 1;
            }
            if (cp >= 97) && (cp <= 122) {
                low += 1;
                if (cp == 105) || (cp == 118) || (cp == 120) || (cp == 108) || (cp == 99) || (cp == 100) || (cp == 109) {
                    rl += 1;
                }
            }
            if (cp >= 65) && (cp <= 90) {
                upr += 1;
                if (cp == 73) || (cp == 86) || (cp == 88) || (cp == 76) || (cp == 67) || (cp == 68) || (cp == 77) {
                    ru += 1;
                }
            }
            if (cp >= 0) && (cp < 48) {
                sym += 1;
            }
            if (cp > 57) && (cp < 65) {
                sym += 1;
            }
            if (cp > 90) && (cp < 97) {
                sym += 1;
            }
            if (cp > 122) && (cp < 128) {
                sym += 1;
            }
            if (cp >= 8192) && (cp <= 11263) {
                sym += 1;
            }
            if (cp >= 57344) && (cp <= 63743) {
                sym += 1;
            }
        }
        g += 1;
    }
    if n == 0 {
        return 0;
    }
    if sym == n {
        return 1;
    }
    if dig == n {
        return 2;
    }
    if low == n {
        mask = 4;
        if rl == n {
            mask = 20;
        }
        return mask;
    }
    if upr == n {
        mask = 8;
        if ru == n {
            mask = 40;
        }
        return mask;
    }
    return 0;
}
pub(crate) fn tg_list_want(ln: i32) -> i32 {
    // The label kinds (`lk` bits) a ListNumbering value allows; 0 when it says nothing to check.
    if (ln == 2) || (ln == 4) || (ln == 5) || (ln == 6) {
        return 1;
    }
    if ln == 3 {
        return 62;
    }
    if ln == 7 {
        return 2;
    }
    if ln == 8 {
        return 32;
    }
    if ln == 9 {
        return 16;
    }
    if ln == 10 {
        return 8;
    }
    if ln == 11 {
        return 4;
    }
    return 0;
}
pub(crate) fn tg_j_lists(sk: &mut crate::port::Cells, mut se: &mut crate::port::Cells, sc: &mut crate::port::Cells, gl: &mut crate::port::Cells) -> i32 {
    // Each list: its items, the items with a label, and whether the first glyphs of each label look like
    // what the list's ListNumbering says (a bullet for Disc, digits for Decimal, ...).
    let nse: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let mut r: i32 = 1;
    let mut at: i32 = 0;
    let mut k: i32 = 0;
    let mut kn: i32 = 0;
    let mut c: i32 = 0;
    let mut li: i32 = 0;
    let mut lat: i32 = 0;
    let mut j: i32 = 0;
    let mut jn: i32 = 0;
    let mut d: i32 = 0;
    let mut bl: i32 = 0;
    let mut bat: i32 = 0;
    let mut haslbl: i32 = 0;
    let mut want: i32 = 0;
    let mut kind: i32 = 0;
    let mut fsc: i32 = 0;
    let mut sat: i32 = 0;
    while r < nse {
        at = r * SE_STRIDE;
        if crate::port::cells_at(se, at + SE_ROLE) == RO_L {
            want = tg_list_want(crate::port::cells_at(se, at + SE_LISTNUM));
            k = crate::port::cells_at(se, at + SE_KFIRST);
            kn = crate::port::cells_at(se, at + SE_KCOUNT);
            c = 0;
            while (k >= 0) && (c < kn) {
                if crate::port::cells_at(sk, (k + c) * SK_STRIDE) == 1 {
                    li = crate::port::cells_at(sk, ((k + c) * SK_STRIDE) + 1);
                    lat = li * SE_STRIDE;
                    if crate::port::cells_at(se, lat + SE_ROLE) == RO_LI {
                        crate::port::cells_set(se, at + SE_LITEMS, crate::port::cells_at(se, at + SE_LITEMS) + 1);
                        haslbl = 0;
                        j = crate::port::cells_at(se, lat + SE_KFIRST);
                        jn = crate::port::cells_at(se, lat + SE_KCOUNT);
                        d = 0;
                        while (j >= 0) && (d < jn) && (haslbl == 0) {
                            if crate::port::cells_at(sk, (j + d) * SK_STRIDE) == 1 {
                                bl = crate::port::cells_at(sk, ((j + d) * SK_STRIDE) + 1);
                                bat = bl * SE_STRIDE;
                                if crate::port::cells_at(se, bat + SE_ROLE) == RO_LBL {
                                    haslbl = 1;
                                    crate::port::cells_set(se, at + SE_LLBL, crate::port::cells_at(se, at + SE_LLBL) + 1);
                                    fsc = crate::port::cells_at(se, bat + SE_FSC);
                                    kind = 0;
                                    if fsc >= 0 {
                                        sat = fsc * SC_STRIDE;
                                        kind = tg_label_kind(gl, crate::port::cells_at(sc, sat + SC_FIRSTG), crate::port::cells_at(sc, sat + SC_LASTG));
                                    }
                                    if crate::port::cells_at(se, at + SE_LKIND) == 0 {
                                        crate::port::cells_set(se, at + SE_LKIND, kind);
                                    }
                                    if (want > 0) && (kind > 0) {
                                        if (want & kind) > 0 {
                                            crate::port::cells_set(se, at + SE_LOK, crate::port::cells_at(se, at + SE_LOK) + 1);
                                        } else {
                                            crate::port::cells_set(se, at + SE_LBAD, crate::port::cells_at(se, at + SE_LBAD) + 1);
                                        }
                                    }
                                }
                            }
                            d += 1;
                        }
                    }
                }
                c += 1;
            }
        }
        r += 1;
    }
    return 0;
}
pub(crate) fn tg_mean(sum: i32, n: i32) -> i32 {
    // sum * 10 / n in centipoints (sums are tenths of a point), without overflow.
    if n <= 0 {
        return 0;
    }
    return ((sum / n) * 10) + (((sum % n) * 10) / n);
}
pub(crate) fn tg_j_headings(mut ss: &mut crate::port::Cells, se: &mut crate::port::Cells, mut hh: &mut crate::port::Cells) -> i32 {
    // Heading roles against the page. The BODY SIZE is the most common size of tagged text. A heading
    // (an element inside H, Hn or Title, with text of its own) is verified when its type is clearly larger
    // than the body or is bold and not smaller; a BIG element is short text at least 1.25 times the body
    // that is not a table cell, a label, a figure or a formula, and is a miss when it is no heading. Heading
    // LEVELS are checked two ways: in document order a level may not jump by more than one, and a
    // lower level number may not be set smaller than a higher one.
    let nse: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let mut b: i32 = 0;
    let mut best: i32 = 0;
    let mut bestn: i32 = 0;
    let mut body: i32 = 0;
    let mut r: i32 = 1;
    let mut at: i32 = 0;
    let mut g: i32 = 0;
    let mut mean: i32 = 0;
    let mut bold: i32 = 0;
    let mut role: i32 = 0;
    let mut inh: i32 = 0;
    let mut lvl: i32 = 0;
    let mut prevl: i32 = 0;
    let mut skip: i32 = 0;
    let mut l: i32 = 0;
    let mut pl: i32 = 0;
    let mut pmean: i32 = 0;
    let mut cmean: i32 = 0;
    while b < 4096 {
        if crate::port::cells_at(hh, b) > bestn {
            bestn = crate::port::cells_at(hh, b);
            best = b;
        }
        b += 1;
    }
    if bestn > 0 {
        body = (best * 50) + 25;
    }
    crate::port::cells_set(ss, SS_BODY, body);
    if body == 0 {
        return 0;
    }
    while r < nse {
        at = r * SE_STRIDE;
        g = crate::port::cells_at(se, at + SE_OWNG);
        role = crate::port::cells_at(se, at + SE_ROLE);
        inh = crate::port::cells_at(se, at + SE_INH);
        if g > 0 {
            mean = tg_mean(crate::port::cells_at(se, at + SE_OWNSZ), g);
            bold = tg_pm(crate::port::cells_at(se, at + SE_OWNBD), g);
            skip = 0;
            if (role == RO_TH) || (role == RO_TD) || (role == RO_LBL) || (role == RO_FORMULA) || (role == RO_FIGURE) {
                skip = 1;
            }
            if (skip == 0) && (inh == 1) {
                crate::port::cells_set(ss, SS_HEADS, crate::port::cells_at(ss, SS_HEADS) + 1);
                if (mean * 100) >= (body * 108) {
                    crate::port::cells_set(ss, SS_HEADSOK, crate::port::cells_at(ss, SS_HEADSOK) + 1);
                } else if (bold >= 700) && ((mean * 100) >= (body * 95)) {
                    crate::port::cells_set(ss, SS_HEADSOK, crate::port::cells_at(ss, SS_HEADSOK) + 1);
                }
            }
            if (skip == 0) && (g <= 300) && ((mean * 100) >= (body * 125)) {
                crate::port::cells_set(ss, SS_BIG, crate::port::cells_at(ss, SS_BIG) + 1);
                if inh == 1 {
                    crate::port::cells_set(ss, SS_BIGHEAD, crate::port::cells_at(ss, SS_BIGHEAD) + 1);
                }
            }
        }
        if (role == RO_HN) && (crate::port::cells_at(se, at + SE_SUBG) > 0) {
            lvl = crate::port::cells_at(se, at + SE_LEVEL);
            mean = tg_mean(crate::port::cells_at(se, at + SE_SUBSZ), crate::port::cells_at(se, at + SE_SUBG));
            if (lvl >= 1) && (lvl <= 6) {
                crate::port::cells_set(hh, 4096 + (lvl * 2), crate::port::cells_at(hh, 4096 + (lvl * 2)) + mean);
                crate::port::cells_set(hh, 4097 + (lvl * 2), crate::port::cells_at(hh, 4097 + (lvl * 2)) + 1);
            }
            if prevl > 0 {
                crate::port::cells_set(ss, SS_LVPAIRS, crate::port::cells_at(ss, SS_LVPAIRS) + 1);
                if lvl <= (prevl + 1) {
                    crate::port::cells_set(ss, SS_LVOK, crate::port::cells_at(ss, SS_LVOK) + 1);
                }
            }
            prevl = lvl;
        }
        r += 1;
    }
    l = 1;
    while l <= 6 {
        if crate::port::cells_at(hh, 4097 + (l * 2)) > 0 {
            cmean = crate::port::cells_at(hh, 4096 + (l * 2)) / crate::port::cells_at(hh, 4097 + (l * 2));
            if pl > 0 {
                crate::port::cells_set(ss, SS_LVPAIRS, crate::port::cells_at(ss, SS_LVPAIRS) + 1);
                if (pmean * 100) >= (cmean * 97) {
                    crate::port::cells_set(ss, SS_LVOK, crate::port::cells_at(ss, SS_LVOK) + 1);
                }
            }
            pl = l;
            pmean = cmean;
        }
        l += 1;
    }
    return 0;
}
pub(crate) fn tg_j_artifacts(mut ss: &mut crate::port::Cells, mut sa: &mut crate::port::Cells, gl: &mut crate::port::Cells, mk: &mut crate::port::Cells, pg: &mut crate::port::Cells) -> i32 {
    // One `sa` row per OUTERMOST artifact span: where its text sits on the page, and whether what it
    // says it is (a header, a footer, pagination, a watermark) agrees: a header lies in the top 12 per cent
    // of the page, a footer in the bottom 12, other furniture in a margin, a watermark is turned, light or
    // large. A span with no text is `unchecked`: a rule or a shading says nothing to verify.
    crate::port::cells_drop(sa, 0);
    let nmk: i32 = mk_count(mk);
    let npg: i32 = pd_pg_count(pg);
    let mut m: i32 = 0;
    let mut p: i32 = 0;
    let mut nested: i32 = 0;
    let mut row: i32 = 0;
    let mut at: i32 = 0;
    let mut pi: i32 = 0;
    let mut g0: i32 = 0;
    let mut gn: i32 = 0;
    let mut g: i32 = 0;
    let mut cnt: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut szs: i32 = 0;
    let mut lum: i32 = 0;
    let mut fill: i32 = 0;
    let mut rot: i32 = 0;
    let mut pw: i32 = 0;
    let mut ph: i32 = 0;
    let mut rt: i32 = 0;
    let mut band: i32 = 0;
    let mut verdict: i32 = 0;
    let mut sub: i32 = 0;
    let mut marginal: i32 = 0;
    let mut wm: i32 = 0;
    let mut meansz: i32 = 0;
    let mut meanlum: i32 = 0;
    let mut i: i32 = 0;
    while m < nmk {
        if mk_get(mk, m, mkf_kind()) == 1 {
            nested = 0;
            p = mk_get(mk, m, mkf_parent());
            while p >= 0 {
                if mk_get(mk, p, mkf_kind()) == 1 {
                    nested = 1;
                }
                p = mk_get(mk, p, mkf_parent());
            }
            if nested == 0 {
                pi = mk_get(mk, m, mkf_page()) - 1;
                g0 = mk_get(mk, m, mkf_gfirst());
                gn = mk_get(mk, m, mkf_gcount());
                cnt = 0;
                x0 = 0;
                y0 = 0;
                x1 = 0;
                y1 = 0;
                szs = 0;
                lum = 0;
                rot = 0;
                g = 0;
                while g < gn {
                    if cnt == 0 {
                        x0 = gl_get(gl, g0 + g, ch_x0());
                        y0 = gl_get(gl, g0 + g, ch_y0());
                        x1 = gl_get(gl, g0 + g, ch_x1());
                        y1 = gl_get(gl, g0 + g, ch_y1());
                        rot = gl_get(gl, g0 + g, gf_rot());
                    } else {
                        x0 = tg_min(x0, gl_get(gl, g0 + g, ch_x0()));
                        y0 = tg_min(y0, gl_get(gl, g0 + g, ch_y0()));
                        x1 = tg_max(x1, gl_get(gl, g0 + g, ch_x1()));
                        y1 = tg_max(y1, gl_get(gl, g0 + g, ch_y1()));
                    }
                    szs += tg_min(tg_max(gl_get(gl, g0 + g, gf_size()), 0), 6000) / 10;
                    fill = gl_get(gl, g0 + g, gf_fill());
                    if fill >= 0 {
                        lum += (((((fill / 65536) & 255) * 299) + (((fill / 256) & 255) * 587)) + ((fill & 255) * 114)) / 1000;
                    }
                    cnt += 1;
                    g += 1;
                }
                sub = mk_get(mk, m, mkf_arsub());
                band = 0;
                verdict = 0;
                meansz = 0;
                meanlum = -1;
                if cnt > 0 {
                    meansz = tg_mean(szs, cnt);
                    meanlum = lum / cnt;
                    pw = 0;
                    ph = 0;
                    if (pi >= 0) && (pi < npg) {
                        pw = pd_pg_crop(pg, pi, 2) - pd_pg_crop(pg, pi, 0);
                        ph = pd_pg_crop(pg, pi, 3) - pd_pg_crop(pg, pi, 1);
                        rt = pd_pg_rotate(pg, pi);
                        if (rt == 90) || (rt == 270) {
                            i = pw;
                            pw = ph;
                            ph = i;
                        }
                    }
                    band = 1;
                    if pw > 0 {
                        if ((y0 + y1) * 100) < (ph * 24) {
                            band = 2;
                        }
                        if ((y0 + y1) * 100) > (ph * 176) {
                            band = 3;
                        }
                        if band == 1 {
                            if (((x0 + x1) * 100) < (pw * 16)) || (((x0 + x1) * 100) > (pw * 184)) {
                                band = 4;
                            }
                        }
                    }
                    marginal = 0;
                    if band > 1 {
                        marginal = 1;
                    }
                    wm = 0;
                    if (rot != 0) || (meanlum >= 170) || (meansz >= 3600) {
                        wm = 1;
                    }
                    if sub == 1 {
                        if band == 2 {
                            verdict = 1;
                        } else {
                            verdict = 2;
                        }
                    }
                    if sub == 2 {
                        if band == 3 {
                            verdict = 1;
                        } else {
                            verdict = 2;
                        }
                    }
                    if sub == 3 {
                        if wm == 1 {
                            verdict = 1;
                        } else {
                            verdict = 2;
                        }
                    }
                    if (sub != 1) && (sub != 2) && (sub != 3) {
                        if (marginal == 1) || (wm == 1) {
                            verdict = 1;
                        } else {
                            verdict = 2;
                        }
                    }
                    if verdict == 1 {
                        crate::port::cells_set(ss, SS_ARTOK, crate::port::cells_at(ss, SS_ARTOK) + 1);
                    }
                    if verdict == 2 {
                        crate::port::cells_set(ss, SS_ARTBAD, crate::port::cells_at(ss, SS_ARTBAD) + 1);
                    }
                    crate::port::cells_set(ss, SS_ARTGLYPHS, crate::port::cells_at(ss, SS_ARTGLYPHS) + cnt);
                }
                row = crate::port::cells_len(sa) / SA_STRIDE;
                at = row * SA_STRIDE;
                i = 0;
                while i < SA_STRIDE {
                    crate::port::cells_push(sa, 0);
                    i += 1;
                }
                crate::port::cells_set(sa, at + 0, m);
                crate::port::cells_set(sa, at + 1, pi);
                crate::port::cells_set(sa, at + 2, mk_get(mk, m, mkf_artype()));
                crate::port::cells_set(sa, at + 3, sub);
                crate::port::cells_set(sa, at + 4, cnt);
                crate::port::cells_set(sa, at + 5, x0);
                crate::port::cells_set(sa, at + 6, y0);
                crate::port::cells_set(sa, at + 7, x1);
                crate::port::cells_set(sa, at + 8, y1);
                crate::port::cells_set(sa, at + 9, band);
                crate::port::cells_set(sa, at + 10, rot);
                crate::port::cells_set(sa, at + 11, meansz);
                crate::port::cells_set(sa, at + 12, verdict);
                crate::port::cells_set(sa, at + 13, meanlum);
                crate::port::cells_set(ss, SS_ARTS, crate::port::cells_at(ss, SS_ARTS) + 1);
            }
        }
        m += 1;
    }
    return 0;
}
pub(crate) fn tg_hv(mut ss: &mut crate::port::Cells, v: i32, w: i32, gate: i32) -> i32 {
    // Add one component to the weighted harmonic mean: `SS_WSUM` is the weights' sum, `SS_HSUM` the sum of
    // weight / value (value floored at `TG_FLOOR`, in millionths) and `SS_MINC` the weakest of the components that
    // verify something (`gate` 1: all but the diversity, which is a prior about the document, not a check).
    if v < 0 {
        return 0;
    }
    if (gate == 1) && (v < crate::port::cells_at(ss, SS_MINC)) {
        crate::port::cells_set(ss, SS_MINC, v);
    }
    crate::port::cells_set(ss, SS_WSUM, crate::port::cells_at(ss, SS_WSUM) + w);
    crate::port::cells_set(ss, SS_HSUM, crate::port::cells_at(ss, SS_HSUM) + ((w * 1000000) / tg_max(v, TG_FLOOR)));
    return 0;
}
pub(crate) fn tg_chance(agree: i32) -> i32 {
    // An agreement rate between two orders, corrected for chance: a coin flip agrees half the time, so half
    // is 0 and all is 1000.
    return tg_max(0, (agree * 2) - 1000);
}
pub(crate) fn tg_div(classes: i32) -> i32 {
    // Role diversity per mille from the number of informative classes in use: none 0 (every block
    // a paragraph says nothing about the document), one 500, two 750, three or more 1000.
    if classes <= 0 {
        return 0;
    }
    if classes == 1 {
        return 500;
    }
    if classes == 2 {
        return 750;
    }
    return 1000;
}
pub(crate) fn tg_j_score(mut ss: &mut crate::port::Cells) -> i32 {
    // The components (per mille, -1 when there is nothing to check), their weighted harmonic mean, and that mean
    // scaled by (1000 + the weakest check) / 2000: no tree is better than its weakest check.
    let glyphs: i32 = crate::port::cells_at(ss, SS_GLYPHS);
    let mut v: i32 = 0;
    let mut hp: i32 = 0;
    let mut hn: i32 = 0;
    let mut hdr: i32 = -1;
    let mut score: i32 = 0;
    let mut trust: i32 = 0;
    let mut prior: i32 = 0;
    let mut ua: i32 = 0;
    crate::port::cells_set(ss, SS_WSUM, 0);
    crate::port::cells_set(ss, SS_HSUM, 0);
    crate::port::cells_set(ss, SS_MINC, 1000);
    if crate::port::cells_at(ss, SS_PRESENT) == 0 {
        return 0;
    }
    prior = 300;
    if crate::port::cells_at(ss, SS_MARKED) == 1 {
        prior = 500;
    }
    if (crate::port::cells_at(ss, SS_MARKED) == 1) && (crate::port::cells_at(ss, SS_UAPART) >= 1) {
        prior = 700;
        ua = 1;
    }
    crate::port::cells_set(ss, SS_PRIOR, prior);
    if glyphs == 0 {
        crate::port::cells_set(ss, SS_STATUS, 1);
        return 0;
    }
    crate::port::cells_set(ss, SS_STATUS, 2);
    crate::port::cells_set(ss, SS_COV, tg_pm(crate::port::cells_at(ss, SS_COVERED) + crate::port::cells_at(ss, SS_ARTG), glyphs));
    crate::port::cells_set(ss, SS_DIV, tg_div(crate::port::cells_at(ss, SS_NCLASSES)));
    if crate::port::cells_at(ss, SS_TRANS) >= TG_MINPAIRS {
        crate::port::cells_set(ss, SS_ORD, tg_chance(tg_pm(crate::port::cells_at(ss, SS_TRANSOK), crate::port::cells_at(ss, SS_TRANS))));
    }
    if crate::port::cells_at(ss, SS_HEADS) > 0 {
        hp = tg_pm(crate::port::cells_at(ss, SS_HEADSOK), crate::port::cells_at(ss, SS_HEADS));
        hn += 1;
    }
    if crate::port::cells_at(ss, SS_BIG) > 0 {
        v = tg_pm(crate::port::cells_at(ss, SS_BIGHEAD), crate::port::cells_at(ss, SS_BIG));
        hp += v;
        hn += 1;
    }
    if hn > 0 {
        hdr = hp / hn;
    }
    crate::port::cells_set(ss, SS_HDR, hdr);
    if crate::port::cells_at(ss, SS_LVPAIRS) >= TG_MINPAIRS {
        crate::port::cells_set(ss, SS_LV, tg_chance(tg_pm(crate::port::cells_at(ss, SS_LVOK), crate::port::cells_at(ss, SS_LVPAIRS))));
    }
    if (crate::port::cells_at(ss, SS_ARTOK) + crate::port::cells_at(ss, SS_ARTBAD)) > 0 {
        crate::port::cells_set(ss, SS_ART, tg_pm(crate::port::cells_at(ss, SS_ARTOK), crate::port::cells_at(ss, SS_ARTOK) + crate::port::cells_at(ss, SS_ARTBAD)));
    }
    if crate::port::cells_at(ss, SS_NEST) > 0 {
        crate::port::cells_set(ss, SS_NESTR, tg_pm(crate::port::cells_at(ss, SS_NESTOK), crate::port::cells_at(ss, SS_NEST)));
    }
    tg_hv(ss, crate::port::cells_at(ss, SS_COV), 3, 1);
    tg_hv(ss, crate::port::cells_at(ss, SS_DIV), 2, 0);
    tg_hv(ss, crate::port::cells_at(ss, SS_ORD), 2, 1);
    tg_hv(ss, crate::port::cells_at(ss, SS_HDR), 2, 1);
    tg_hv(ss, crate::port::cells_at(ss, SS_LV), 2, 1);
    tg_hv(ss, crate::port::cells_at(ss, SS_ART), 2, 1);
    tg_hv(ss, crate::port::cells_at(ss, SS_NESTR), 1, 1);
    if crate::port::cells_at(ss, SS_HSUM) > 0 {
        score = (crate::port::cells_at(ss, SS_WSUM) * 1000000) / crate::port::cells_at(ss, SS_HSUM);
    }
    score = (score * (1000 + tg_max(0, crate::port::cells_at(ss, SS_MINC)))) / 2000;
    score = tg_min(score, 1000);
    crate::port::cells_set(ss, SS_SCORE, score);
    trust = score;
    if ua == 1 {
        trust = tg_min(1000, score + (score / 10));
    }
    crate::port::cells_set(ss, SS_TRUST, trust);
    return 0;
}
pub fn tg_join(mut ss: &mut crate::port::Cells, mut se: &mut crate::port::Cells, sk: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, so: &mut crate::port::Cells, mut sa: &mut crate::port::Cells, gl: &mut crate::port::Cells, mk: &mut crate::port::Cells, fnt: &mut crate::port::Cells, pg: &mut crate::port::Cells, mut ha: &mut crate::port::Cells, mut hb: &mut crate::port::Cells, mut hh: &mut crate::port::Cells) -> i32 {
    // Join the tree to the text layer and score it, after `tg-read` and the content interpreter
    // (`gl mk fnt` are its glyphs, marked content and fonts; `pg` the page table). `sa` is cleared; `ha hb
    // hh` are scratch. Answers 0, or -1 when the tree is absent or the text layer too large (3,000,000
    // glyphs) for the sums to fit.
    if crate::port::cells_at(ss, SS_PRESENT) == 0 {
        tg_j_score(ss);
        return -1;
    }
    if gl_count(gl) > 3000000 {
        return -1;
    }
    tg_j_marks(ss, sc, mk, ha, hb);
    tg_j_glyphs(ss, sc, gl, mk, fnt, hb, hh);
    tg_j_sub(ss, se, sc, so);
    tg_j_order(ss, sc, gl);
    tg_j_classes(ss, se);
    tg_j_tables(sk, se);
    tg_j_lists(sk, se, sc, gl);
    tg_j_headings(ss, se, hh);
    tg_j_artifacts(ss, sa, gl, mk, pg);
    tg_j_score(ss);
    return 0;
}
