pub(crate) fn tg_dump_elem(mut t: &mut String, txt: &mut crate::port::Cells, se: &mut crate::port::Cells, sk: &mut crate::port::Cells, row: i32) -> i32 {
    let at: i32 = row * SE_STRIDE;
    let mut k: i32 = 0;
    let mut kn: i32 = 0;
    let mut j: i32 = 0;
    let mut v: i32 = 0;
    crate::port::text_ascii(t, "{\"obj\":");
    crate::port::text_i32(t, crate::port::cells_at(se, at + SE_OBJ));
    crate::port::text_ascii(t, ",\"parent\":");
    crate::port::text_i32(t, crate::port::cells_at(se, at + SE_PARENT));
    crate::port::text_ascii(t, ",\"depth\":");
    crate::port::text_i32(t, crate::port::cells_at(se, at + SE_DEPTH));
    crate::port::text_ascii(t, ",\"s\":");
    tg_dump_run(t, txt, se, at + SE_ROLES);
    crate::port::text_ascii(t, ",\"role\":");
    if crate::port::cells_at(se, at + SE_ROLE) == 0 {
        crate::port::text_ascii(t, "null");
    } else {
        crate::port::text_ascii(t, "\"");
        if crate::port::cells_at(se, at + SE_ROLE) == RO_HN {
            crate::port::text_ascii(t, "H");
            crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LEVEL));
        } else {
            sr_emit_name(t, crate::port::cells_at(se, at + SE_ROLE));
        }
        crate::port::text_ascii(t, "\"");
    }
    crate::port::text_ascii(t, ",\"how\":\"");
    tg_how_emit_name(t, crate::port::cells_at(se, at + SE_HOW));
    crate::port::text_ascii(t, "\"");
    if crate::port::cells_at(se, at + SE_HLEV) > 0 {
        crate::port::text_ascii(t, ",\"hlevel\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_HLEV));
    }
    if crate::port::cells_at(se, at + SE_PG) >= 0 {
        crate::port::text_ascii(t, ",\"page\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_PG));
    }
    crate::port::text_ascii(t, ",\"kids\":[");
    k = crate::port::cells_at(se, at + SE_KFIRST);
    kn = crate::port::cells_at(se, at + SE_KCOUNT);
    j = 0;
    while (k >= 0) && (j < kn) {
        if j > 0 {
            crate::port::text_ascii(t, ",");
        }
        v = (k + j) * SK_STRIDE;
        crate::port::text_ascii(t, "[\"");
        tg_kind_emit_name(t, crate::port::cells_at(sk, v));
        crate::port::text_ascii(t, "\",");
        crate::port::text_i32(t, crate::port::cells_at(sk, v + 1));
        crate::port::text_ascii(t, "]");
        j += 1;
    }
    crate::port::text_ascii(t, "]");
    if crate::port::cells_at(se, at + SE_ALT) >= 0 {
        crate::port::text_ascii(t, ",\"alt\":");
        tg_dump_run(t, txt, se, at + SE_ALT);
    }
    if crate::port::cells_at(se, at + SE_ACT) >= 0 {
        crate::port::text_ascii(t, ",\"actualText\":");
        tg_dump_run(t, txt, se, at + SE_ACT);
    }
    if crate::port::cells_at(se, at + SE_EXP) >= 0 {
        crate::port::text_ascii(t, ",\"expansion\":");
        tg_dump_run(t, txt, se, at + SE_EXP);
    }
    if crate::port::cells_at(se, at + SE_LANG) >= 0 {
        crate::port::text_ascii(t, ",\"lang\":");
        tg_dump_run(t, txt, se, at + SE_LANG);
    }
    if crate::port::cells_at(se, at + SE_LANGSRC) != -1 {
        crate::port::text_ascii(t, ",\"langFrom\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LANGSRC));
    }
    if crate::port::cells_at(se, at + SE_ID) >= 0 {
        crate::port::text_ascii(t, ",\"id\":");
        tg_dump_run(t, txt, se, at + SE_ID);
    }
    if crate::port::cells_at(se, at + SE_TITLE) >= 0 {
        crate::port::text_ascii(t, ",\"title\":");
        tg_dump_run(t, txt, se, at + SE_TITLE);
    }
    if crate::port::cells_at(se, at + SE_SCOPE) > 0 {
        crate::port::text_ascii(t, ",\"scope\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_SCOPE));
    }
    if crate::port::cells_at(se, at + SE_ROWSPAN) >= 0 {
        crate::port::text_ascii(t, ",\"rowSpan\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_ROWSPAN));
    }
    if crate::port::cells_at(se, at + SE_COLSPAN) >= 0 {
        crate::port::text_ascii(t, ",\"colSpan\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_COLSPAN));
    }
    if crate::port::cells_at(se, at + SE_HEADS) >= 0 {
        crate::port::text_ascii(t, ",\"headers\":");
        tg_dump_run(t, txt, se, at + SE_HEADS);
    }
    if crate::port::cells_at(se, at + SE_SUMM) >= 0 {
        crate::port::text_ascii(t, ",\"summary\":");
        tg_dump_run(t, txt, se, at + SE_SUMM);
    }
    if crate::port::cells_at(se, at + SE_LISTNUM) > 0 {
        crate::port::text_ascii(t, ",\"listNumbering\":\"");
        tg_listnum_emit_name(t, crate::port::cells_at(se, at + SE_LISTNUM));
        crate::port::text_ascii(t, "\"");
    }
    crate::port::text_ascii(t, ",\"bits\":");
    crate::port::text_i32(t, crate::port::cells_at(se, at + SE_BITS));
    crate::port::text_ascii(t, ",\"size\":");
    crate::port::text_i32(t, crate::port::cells_at(se, at + SE_SIZE));
    if crate::port::cells_at(se, at + SE_SUBC) > 0 {
        crate::port::text_ascii(t, ",\"content\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_SUBC));
    }
    if crate::port::cells_at(se, at + SE_SUBG) > 0 {
        crate::port::text_ascii(t, ",\"glyphs\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_SUBG));
        crate::port::text_ascii(t, ",\"ownGlyphs\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_OWNG));
        crate::port::text_ascii(t, ",\"meanSize\":");
        px_json_cp(t, tg_mean(crate::port::cells_at(se, at + SE_SUBSZ), crate::port::cells_at(se, at + SE_SUBG)));
        crate::port::text_ascii(t, ",\"bold\":");
        crate::port::text_i32(t, tg_pm(crate::port::cells_at(se, at + SE_SUBBD), crate::port::cells_at(se, at + SE_SUBG)));
        crate::port::text_ascii(t, ",\"firstPage\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_FPG));
        crate::port::text_ascii(t, ",\"box\":");
        px_json_box(t, se, at + SE_BX0);
    }
    if crate::port::cells_at(se, at + SE_TROWS) > 0 {
        crate::port::text_ascii(t, ",\"rows\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_TROWS));
        crate::port::text_ascii(t, ",\"cols\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_TCOLS));
        crate::port::text_ascii(t, ",\"regular\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_TREG));
    }
    if crate::port::cells_at(se, at + SE_LITEMS) > 0 {
        crate::port::text_ascii(t, ",\"items\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LITEMS));
        crate::port::text_ascii(t, ",\"labelled\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LLBL));
        crate::port::text_ascii(t, ",\"labelsAgree\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LOK));
        crate::port::text_ascii(t, ",\"labelsDiffer\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LBAD));
        crate::port::text_ascii(t, ",\"labelKind\":");
        crate::port::text_i32(t, crate::port::cells_at(se, at + SE_LKIND));
    }
    crate::port::text_ascii(t, "}");
    return 0;
}
