pub fn tg_dump(mut t: &mut String, txt: &mut crate::port::Cells, ss: &mut crate::port::Cells, se: &mut crate::port::Cells, sk: &mut crate::port::Cells, sc: &mut crate::port::Cells, so: &mut crate::port::Cells, sa: &mut crate::port::Cells) -> i32 {
    // The tree, the join and the score as one canonical JSON object: `{"tree":{..},"score":{..},
    // "elements":[..],"content":[..],"objr":[..],"artifacts":[..]}`, rows in arena order.
    // Not a public contract (the Model says what it needs of these): what the laws and the oracle compare.
    let nse: i32 = crate::port::cells_len(se) / SE_STRIDE;
    let nsc: i32 = crate::port::cells_len(sc) / SC_STRIDE;
    let nso: i32 = crate::port::cells_len(so) / SO_STRIDE;
    let nsa: i32 = crate::port::cells_len(sa) / SA_STRIDE;
    let mut i: i32 = 0;
    let mut at: i32 = 0;
    crate::port::text_ascii(t, "{\"tree\":{\"present\":");
    tg_dump_kv(t, ss, SS_PRESENT);
    crate::port::text_ascii(t, ",\"marked\":");
    tg_dump_kv(t, ss, SS_MARKED);
    crate::port::text_ascii(t, ",\"suspects\":");
    tg_dump_kv(t, ss, SS_SUSPECTS);
    crate::port::text_ascii(t, ",\"userProperties\":");
    tg_dump_kv(t, ss, SS_USERPROPS);
    crate::port::text_ascii(t, ",\"pdfuaPart\":");
    tg_dump_kv(t, ss, SS_UAPART);
    crate::port::text_ascii(t, ",\"pdfuaRev\":");
    tg_dump_kv(t, ss, SS_UAREV);
    crate::port::text_ascii(t, ",\"lang\":");
    tg_dump_run(t, txt, ss, SS_LANG);
    crate::port::text_ascii(t, ",\"elements\":");
    tg_dump_kv(t, ss, SS_ELEMS);
    crate::port::text_ascii(t, ",\"content\":");
    tg_dump_kv(t, ss, SS_CONTENT);
    crate::port::text_ascii(t, ",\"objr\":");
    tg_dump_kv(t, ss, SS_OBJRS);
    crate::port::text_ascii(t, ",\"depth\":");
    tg_dump_kv(t, ss, SS_MAXDEPTH);
    crate::port::text_ascii(t, ",\"limits\":");
    tg_dump_kv(t, ss, SS_LIMITS);
    crate::port::text_ascii(t, ",\"roleMap\":");
    tg_dump_kv(t, ss, SS_ROLEMAPN);
    crate::port::text_ascii(t, ",\"classMap\":");
    tg_dump_kv(t, ss, SS_CLASSMAPN);
    crate::port::text_ascii(t, ",\"customRoles\":");
    tg_dump_kv(t, ss, SS_CUSTOM);
    crate::port::text_ascii(t, ",\"unresolvedRoles\":");
    tg_dump_kv(t, ss, SS_UNRESOLVED);
    crate::port::text_ascii(t, ",\"shadowedRoles\":");
    tg_dump_kv(t, ss, SS_SHADOWED);
    crate::port::text_ascii(t, ",\"parentTree\":[");
    tg_dump_kv(t, ss, SS_PTKEYS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_PTOK);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_PTBAD);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_PTNONE);
    crate::port::text_ascii(t, "],\"tables\":");
    tg_dump_kv(t, ss, SS_TABLES);
    crate::port::text_ascii(t, ",\"lists\":");
    tg_dump_kv(t, ss, SS_LISTS);
    crate::port::text_ascii(t, "},\"score\":{\"status\":");
    tg_dump_kv(t, ss, SS_STATUS);
    crate::port::text_ascii(t, ",\"marks\":");
    tg_dump_kv(t, ss, SS_MARKS);
    crate::port::text_ascii(t, ",\"joined\":");
    tg_dump_kv(t, ss, SS_JOINED);
    crate::port::text_ascii(t, ",\"unjoined\":");
    tg_dump_kv(t, ss, SS_UNJOINED);
    crate::port::text_ascii(t, ",\"duplicates\":");
    tg_dump_kv(t, ss, SS_DUPS);
    crate::port::text_ascii(t, ",\"glyphs\":[");
    tg_dump_kv(t, ss, SS_GLYPHS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_COVERED);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_ARTG);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_UNTAGGED);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_UNCLAIMED);
    crate::port::text_ascii(t, "],\"order\":[");
    tg_dump_kv(t, ss, SS_TRANS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_TRANSOK);
    crate::port::text_ascii(t, "],\"classes\":");
    tg_dump_kv(t, ss, SS_CLASSES);
    crate::port::text_ascii(t, ",\"headings\":[");
    tg_dump_kv(t, ss, SS_HEADS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_HEADSOK);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_BIG);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_BIGHEAD);
    crate::port::text_ascii(t, "],\"bodySize\":");
    px_json_cp(t, crate::port::cells_at(ss, SS_BODY));
    crate::port::text_ascii(t, ",\"levels\":[");
    tg_dump_kv(t, ss, SS_LVPAIRS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_LVOK);
    crate::port::text_ascii(t, "],\"nesting\":[");
    tg_dump_kv(t, ss, SS_NEST);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_NESTOK);
    crate::port::text_ascii(t, "],\"artifacts\":[");
    tg_dump_kv(t, ss, SS_ARTS);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_ARTOK);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_ARTBAD);
    crate::port::text_ascii(t, ",");
    tg_dump_kv(t, ss, SS_ARTGLYPHS);
    crate::port::text_ascii(t, "],\"coverage\":");
    tg_dump_kv(t, ss, SS_COV);
    crate::port::text_ascii(t, ",\"diversity\":");
    tg_dump_kv(t, ss, SS_DIV);
    crate::port::text_ascii(t, ",\"readingOrder\":");
    tg_dump_kv(t, ss, SS_ORD);
    crate::port::text_ascii(t, ",\"headingFit\":");
    tg_dump_kv(t, ss, SS_HDR);
    crate::port::text_ascii(t, ",\"levelFit\":");
    tg_dump_kv(t, ss, SS_LV);
    crate::port::text_ascii(t, ",\"artifactFit\":");
    tg_dump_kv(t, ss, SS_ART);
    crate::port::text_ascii(t, ",\"nestingFit\":");
    tg_dump_kv(t, ss, SS_NESTR);
    crate::port::text_ascii(t, ",\"score\":");
    tg_dump_kv(t, ss, SS_SCORE);
    crate::port::text_ascii(t, ",\"prior\":");
    tg_dump_kv(t, ss, SS_PRIOR);
    crate::port::text_ascii(t, ",\"trust\":");
    tg_dump_kv(t, ss, SS_TRUST);
    crate::port::text_ascii(t, "},\"elements\":[");
    while i < nse {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        tg_dump_elem(t, txt, se, sk, i);
        i += 1;
    }
    crate::port::text_ascii(t, "],\"content\":[");
    i = 0;
    while i < nsc {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        tg_dump_content(t, sc, i);
        i += 1;
    }
    crate::port::text_ascii(t, "],\"objr\":[");
    i = 0;
    while i < nso {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        at = i * SO_STRIDE;
        crate::port::text_ascii(t, "[");
        crate::port::text_i32(t, crate::port::cells_at(so, at));
        crate::port::text_ascii(t, ",");
        crate::port::text_i32(t, crate::port::cells_at(so, at + 1));
        crate::port::text_ascii(t, ",");
        crate::port::text_i32(t, crate::port::cells_at(so, at + 2));
        crate::port::text_ascii(t, ",\"");
        tg_objr_emit_name(t, crate::port::cells_at(so, at + 3));
        crate::port::text_ascii(t, "\",");
        crate::port::text_i32(t, crate::port::cells_at(so, at + 4));
        crate::port::text_ascii(t, "]");
        i += 1;
    }
    crate::port::text_ascii(t, "],\"artifactSpans\":[");
    i = 0;
    while i < nsa {
        if i > 0 {
            crate::port::text_ascii(t, ",");
        }
        at = i * SA_STRIDE;
        crate::port::text_ascii(t, "{\"mark\":");
        crate::port::text_i32(t, crate::port::cells_at(sa, at));
        crate::port::text_ascii(t, ",\"page\":");
        crate::port::text_i32(t, crate::port::cells_at(sa, at + 1));
        crate::port::text_ascii(t, ",\"type\":");
        crate::port::text_i32(t, crate::port::cells_at(sa, at + 2));
        crate::port::text_ascii(t, ",\"subtype\":");
        crate::port::text_i32(t, crate::port::cells_at(sa, at + 3));
        crate::port::text_ascii(t, ",\"glyphs\":");
        crate::port::text_i32(t, crate::port::cells_at(sa, at + 4));
        if crate::port::cells_at(sa, at + 4) > 0 {
            crate::port::text_ascii(t, ",\"box\":");
            px_json_box(t, sa, at + 5);
            crate::port::text_ascii(t, ",\"rot\":");
            crate::port::text_i32(t, crate::port::cells_at(sa, at + 10));
            crate::port::text_ascii(t, ",\"size\":");
            px_json_cp(t, crate::port::cells_at(sa, at + 11));
            crate::port::text_ascii(t, ",\"luminance\":");
            crate::port::text_i32(t, crate::port::cells_at(sa, at + 13));
        }
        crate::port::text_ascii(t, ",\"where\":\"");
        tg_band_emit_name(t, crate::port::cells_at(sa, at + 9));
        crate::port::text_ascii(t, "\",\"verdict\":\"");
        tg_verdict_emit_name(t, crate::port::cells_at(sa, at + 12));
        crate::port::text_ascii(t, "\"}");
        i += 1;
    }
    crate::port::text_ascii(t, "]}");
    return 0;
}
pub fn tg_trust(ss: &mut crate::port::Cells) -> i32 {
    // The tree's TRUST (D150): the informativeness score, raised a tenth by a PDF/UA claim; 0 when there is no tree, no
    // text to check, or `tg-join` has not run. What other stages weigh the tree's word by (D034, D076).
    if crate::port::cells_len(ss) <= SS_TRUST {
        return 0;
    }
    return crate::port::cells_at(ss, SS_TRUST);
}
